// GENERATED FILE. Source of truth: docs/data/biblia-emanus/*.json
import type { PublishedEmanusOtTextBook } from "../publishedEmanusOtText.js"

export const EMANUS_TEXT_BOOK: PublishedEmanusOtTextBook = {
  order: 2,
  code: "EXO",
  name: "Exodul",
  chapters: {
    1: ["Iată numele fiilor lui Israel care au venit în Egipt cu Iacov, fiecare cu familia lui:", "Ruben, Simeon, Levi și Iuda,", "Isahar, Zabulon și Beniamin,", "Dan și Neftali, Gad și Așer.", "Toate persoanele care se trăgeau din Iacov erau șaptezeci; Iosif era deja în Egipt.", "Iosif a murit, precum și toți frații lui și toată generația aceea.", "Fiii lui Israel au fost roditori, s-au înmulțit peste măsură, au sporit și au devenit extrem de puternici, așa că țara s-a umplut de ei.", "În Egipt s-a ridicat un rege nou, care nu-l cunoscuse pe Iosif.", "El a zis poporului său: „Iată că poporul fiilor lui Israel este mai numeros și mai puternic decât noi.", "Veniți să ne purtăm cu înțelepciune față de el, ca să nu se înmulțească și, dacă va izbucni vreun război, să nu se alăture vrăjmașilor noștri, să lupte împotriva noastră și să plece din țară.”", "De aceea au pus peste ei supraveghetori ai muncii silnice, ca să-i asuprească prin poverile lor. Astfel au construit pentru faraon cetățile-depozit Pitom și Ramses.", "Dar cu cât îi asupreau mai mult, cu atât se înmulțeau și se răspândeau mai mult, iar egiptenii au ajuns să se îngrozească de fiii lui Israel.", "Egiptenii i-au supus pe fiii lui Israel la o muncă grea, cu cruzime,", "și le-au făcut viața amară prin muncă aspră la lut, la cărămizi și la tot felul de munci de pe câmp; în toate aceste munci îi chinuiau cu cruzime.", "Regele Egiptului le-a vorbit moașelor evreice, dintre care una se numea Șifra, iar cealaltă Pua,", "și le-a spus: „Când le ajutați pe femeile evreice să nască și le vedeți pe scaunul de naștere, dacă este băiat, să-l omorâți, iar dacă este fată, să o lăsați să trăiască.”", "Dar moașele s-au temut de Dumnezeu și n-au făcut ce le poruncise împăratul Egiptului, ci au lăsat băieții să trăiască.", "Împăratul Egiptului le-a chemat pe moașe și le-a zis: „Pentru ce ați făcut lucrul acesta și ați lăsat băieții să trăiască?”", "Moașele i-au răspuns lui Faraon: „Femeile evreice nu sunt ca cele egiptence; ele sunt vânjoase și nasc înainte de a ajunge moașa la ele.”", "Dumnezeu le-a făcut bine moașelor, iar poporul s-a înmulțit și a ajuns foarte puternic.", "Fiindcă moașele s-au temut de Dumnezeu, El le-a întemeiat familii.", "Atunci Faraon a dat următoarea poruncă întregului său popor: „Orice băiat care se va naște să-l aruncați în Nil, iar pe orice fată să o lăsați să trăiască.”"],
    2: ["Un bărbat din casa lui Levi s-a căsătorit cu o femeie dintre fiicele lui Levi.", "Femeia a rămas însărcinată și a născut un fiu. Văzând că este frumos, l-a ascuns trei luni.", "Nemaiputând să-l ascundă, a luat pentru el un coș din papirus, l-a acoperit cu bitum și smoală, a pus copilul în el și l-a așezat între trestii, pe malul Nilului.", "Sora copilului stătea la o oarecare depărtare ca să vadă ce i se va întâmpla.", "Fiica faraonului a coborât la Nil ca să se scalde, iar însoțitoarele ei se plimbau pe mal. Ea a văzut coșul printre trestii și și-a trimis slujitoarea să-l aducă.", "L-a deschis și a văzut copilul: era un băiețel care plângea. I s-a făcut milă de el și a zis: „Este unul dintre copiii evreilor.”", "Atunci sora copilului i-a zis fiicei lui Faraon: „Să mă duc să-ți chem o doică dintre femeile evreice, ca să-ți alăpteze copilul?”", "„Du-te”, i-a răspuns fiica lui Faraon. Și fata s-a dus și a chemat pe mama copilului.", "Fiica lui Faraon i-a zis: „Ia copilul acesta, alăptează-mi-l și îți voi da plata.” Femeia a luat copilul și l-a alăptat.", "Când copilul a crescut, mama lui l-a adus fiicei faraonului, iar el a devenit fiul ei. Ea i-a pus numele Moise și a spus: „Pentru că l-am scos din apă.”", "În vremea aceea, Moise, ajungând mare, a ieșit la frații săi și le-a văzut muncile grele. A văzut pe un egiptean lovind pe un evreu dintre frații lui.", "S-a uitat în toate părțile și, văzând că nu este nimeni, l-a ucis pe egiptean și l-a ascuns în nisip.", "A ieșit și în ziua următoare, și iată că doi evrei se certau. El i-a zis celui ce nedreptățea: „Pentru ce-l lovești pe semenul tău?”", "Dar el a răspuns: „Cine te-a pus pe tine domn și judecător peste noi? Vrei să mă ucizi și pe mine cum l-ai ucis pe egiptean?” Moise s-a temut și a zis: „Cu adevărat, lucrul este cunoscut!”", "Faraonul a auzit despre acest lucru și a căutat să-l omoare pe Moise. Moise însă a fugit de faraon, a locuit în țara Madian și s-a așezat lângă o fântână.", "Preotul din Madian avea șapte fiice. Ele au venit să scoată apă și au umplut jgheaburile ca să adape turma tatălui lor.", "Dar păstorii au venit și le-au alungat. Atunci Moise s-a ridicat, le-a sărit în ajutor și le-a adăpat turma.", "Când s-au întors ele la Reuel, tatăl lor, el le-a întrebat: „Pentru ce v-ați întors așa de curând astăzi?”", "Ele au răspuns: „Un om egiptean ne-a scăpat din mâna păstorilor, ba chiar ne-a scos apă și a adăpat turma.”", "El le-a zis fiicelor sale: „Și unde este? De ce ați lăsat pe omul acela acolo? Chemați-l să mănânce pâine!”", "Moise a primit să locuiască împreună cu acel om, iar acesta i-a dat-o de soție pe fiica sa Sefora.", "Ea a născut un fiu, căruia el i-a pus numele Gherșom, „căci”, a zis el, „locuiesc ca străin într-o țară străină”.", "După multă vreme, regele Egiptului a murit. Fiii lui Israel gemeau din cauza robiei și strigau după ajutor, iar strigătul lor din robie s-a înălțat până la Dumnezeu.", "Dumnezeu a auzit suspinele lor și Și-a adus aminte de legământul Său cu Avraam, cu Isaac și cu Iacov.", "Dumnezeu i-a privit pe fiii lui Israel și a luat seama la ei."],
    3: ["Moise păștea turma lui Ietro, socrul său, preotul Madianului. A mânat turma dincolo de pustiu și a ajuns la muntele lui Dumnezeu, la Horeb.", "Îngerul DOMNULUI i s-a arătat într-o flacără de foc, din mijlocul unui rug. Moise s-a uitat și iată că rugul ardea în foc, dar rugul nu se mistuia.", "Moise a spus: „Mă voi abate să văd această priveliște măreață: de ce nu se mistuie rugul?”", "DOMNUL a văzut că el se întoarce să vadă; și Dumnezeu l-a chemat din mijlocul rugului și a zis: „Moise! Moise!” El a răspuns: „Iată-mă!”", "Dumnezeu a spus: „Nu te apropia! Scoate-ți sandalele din picioare, căci locul pe care stai este pământ sfânt.”", "Apoi a zis: „Eu sunt Dumnezeul tatălui tău, Dumnezeul lui Avraam, Dumnezeul lui Isaac și Dumnezeul lui Iacov.” Moise și-a ascuns fața, căci se temea să se uite la Dumnezeu.", "DOMNUL a zis: „Am văzut suferința poporului Meu care este în Egipt și am auzit strigătele pe care le scoate din cauza supraveghetorilor lui; căci îi cunosc durerile.", "M-am coborât ca să-i izbăvesc din mâna egiptenilor și să-i scot din țara aceasta într-o țară bună și întinsă, într-o țară în care curge lapte și miere, în ținutul canaaniților, hetiților, amoriților, periziților, heviților și iebusiților.", "Acum iată că strigătul fiilor lui Israel a ajuns până la Mine și am văzut asuprirea cu care îi chinuiesc egiptenii.", "Acum vino, te voi trimite la Faraon, și vei scoate din Egipt pe poporul Meu, pe fiii lui Israel!”", "Moise I-a zis lui Dumnezeu: „Cine sunt eu, ca să mă duc la Faraon și să scot pe fiii lui Israel din Egipt?”", "Dumnezeu a zis: „Eu voi fi cu tine; și acesta va fi pentru tine semnul că Eu te-am trimis: după ce vei scoate poporul din Egipt, vă veți închina lui Dumnezeu pe muntele acesta.”", "Moise I-a zis lui Dumnezeu: „Iată, când voi merge la fiii lui Israel și le voi spune: «Dumnezeul părinților voștri m-a trimis la voi», iar ei mă vor întreba: «Care este Numele Lui?», ce le voi răspunde?”", "Dumnezeu i-a spus lui Moise: „EU SUNT CEL CE SUNT.” Apoi a spus: „Așa să le vorbești fiilor lui Israel: «EU SUNT m-a trimis la voi.»”", "Dumnezeu i-a mai spus lui Moise: „Așa să le vorbești fiilor lui Israel: «DOMNUL, Dumnezeul părinților voștri, Dumnezeul lui Avraam, Dumnezeul lui Isaac și Dumnezeul lui Iacov, m-a trimis la voi.» Acesta este Numele Meu pentru totdeauna și astfel voi fi amintit din generație în generație.", "Du-te, adună-i pe bătrânii lui Israel și spune-le: «DOMNUL, Dumnezeul părinților voștri, Dumnezeul lui Avraam, al lui Isaac și al lui Iacov, mi S-a arătat și a spus: Am luat seama la voi și la ce vi se face în Egipt.", "și am zis: Vă voi scoate din suferința Egiptului și vă voi duce în țara canaaniților, hitiților, amoriților, fereziților, heviților și iebusiților, într-o țară în care curge lapte și miere.»", "Ei vor asculta de glasul tău. Tu și bătrânii lui Israel veți merge la regele Egiptului și îi veți spune: «DOMNUL, Dumnezeul evreilor, ni S-a arătat. Lasă-ne, te rugăm, să mergem cale de trei zile în pustiu, ca să aducem jertfe DOMNULUI, Dumnezeul nostru.»", "Știu că regele Egiptului nu vă va lăsa să plecați dacă nu va fi constrâns de o mână puternică.", "Eu Îmi voi întinde mâna și voi lovi Egiptul cu toate minunile Mele pe care le voi face în mijlocul lui; după aceea vă va lăsa să plecați.", "Voi face ca poporul acesta să capete trecere în ochii egiptenilor; și când veți pleca, nu veți pleca cu mâinile goale.", "Fiecare femeie va cere de la vecina ei și de la femeia care locuiește în casa ei obiecte de argint, obiecte de aur și haine. Le veți pune pe fiii și pe fiicele voastre; astfel veți lua prada Egiptului.”"],
    4: ["Moise a răspuns și a zis: „Dar iată că ei nu mă vor crede și nu vor asculta de glasul meu, ci vor zice: «Nu ți s-a arătat DOMNUL!»”", "DOMNUL i-a zis: „Ce ai în mână?” El a răspuns: „Un toiag.”", "DOMNUL a zis: „Aruncă-l pe pământ!” El l-a aruncat pe pământ și toiagul s-a prefăcut într-un șarpe. Moise fugea dinaintea lui.", "DOMNUL i-a zis lui Moise: „Întinde-ți mâna și apucă-l de coadă!” El și-a întins mâna și l-a apucat, și șarpele s-a prefăcut iarăși într-un toiag în mâna lui.", "„Aceasta este”, a zis DOMNUL, „ca să creadă că ți s-a arătat DOMNUL, Dumnezeul părinților lor, Dumnezeul lui Avraam, Dumnezeul lui Isaac și Dumnezeul lui Iacov.”", "DOMNUL i-a mai spus: „Bagă-ți mâna în sân!” El și-a băgat mâna în sân, iar când a scos-o, mâna lui era albă ca zăpada, acoperită de o boală de piele.", "DOMNUL a spus: „Bagă-ți din nou mâna în sân!” El și-a băgat din nou mâna în sân, iar când a scos-o, aceasta revenise la starea celuilalt trup al său.", "„Dacă nu te vor crede”, a zis DOMNUL, „și nu vor asculta de glasul primului semn, te vor crede la glasul celui de-al doilea semn.", "Iar dacă nu vor crede nici cele două semne și nu vor asculta de glasul tău, vei lua apă din Nil și o vei turna pe uscat; și apa pe care o vei lua din Nil se va preface în sânge pe uscat.”", "Moise I-a spus DOMNULUI: „Te rog, Doamne, eu nu sunt un om cu vorbire ușoară, nici de ieri, nici de alaltăieri, nici de când îi vorbești slujitorului Tău; sunt greoi la vorbire și greoi la limbă.”", "DOMNUL i-a zis: „Cine a făcut gura omului? Sau cine face pe om mut sau surd, cu vedere sau orb? Oare nu Eu, DOMNUL?", "Du-te dar acum; Eu voi fi cu gura ta și te voi învăța ce să vorbești.”", "Moise a spus: „Te rog, Doamne, trimite pe altcineva!”", "Atunci DOMNUL S-a aprins de mânie împotriva lui Moise și a zis: „Oare nu este fratele tău Aaron, levitul? Știu că el vorbește bine. Iată că el însuși îți iese în întâmpinare și, când te va vedea, se va bucura în inima lui.", "Tu îi vei vorbi și vei pune cuvintele în gura lui; iar Eu voi fi cu gura ta și cu gura lui și vă voi învăța ce să faceți.", "El va vorbi poporului în locul tău; el îți va fi gură, iar tu vei fi pentru el ca Dumnezeu.", "Ia în mână toiagul acesta cu care vei face semnele.”", "Moise s-a întors la Ietro, socrul său, și i-a spus: „Lasă-mă, te rog, să mă întorc la frații mei care sunt în Egipt, ca să văd dacă mai sunt în viață.” Ietro i-a spus lui Moise: „Du-te în pace!”", "DOMNUL i-a zis lui Moise în Madian: „Du-te, întoarce-te în Egipt, căci toți oamenii care îți căutau viața au murit.”", "Moise și-a luat nevasta și fiii, i-a suit pe un măgar și s-a întors în țara Egiptului. Moise a luat în mână și toiagul lui Dumnezeu.", "DOMNUL i-a zis lui Moise: „Plecând ca să te întorci în Egipt, vezi să faci înaintea lui Faraon toate minunile pe care ți le-am pus în mână. Dar Eu îi voi împietri inima și nu va lăsa poporul să plece.", "Tu îi vei spune lui Faraon: «Așa vorbește DOMNUL: Israel este fiul Meu, întâiul Meu născut.", "Îți spun: Lasă pe fiul Meu să plece, ca să-Mi slujească; dar dacă refuzi să-l lași să plece, iată că îl voi ucide pe fiul tău, pe întâiul tău născut.»”", "Pe drum, la un loc de popas, DOMNUL l-a întâlnit și a căutat să-l omoare.", "Atunci Sefora a luat o piatră ascuțită, a tăiat prepuțul fiului ei și i-a atins picioarele cu el, spunând: „Cu adevărat, ești pentru mine un mire de sânge!”", "Atunci DOMNUL l-a lăsat. Ea spusese „mire de sânge” din cauza circumciziei.", "DOMNUL i-a zis lui Aaron: „Du-te în pustiu în întâmpinarea lui Moise!” El s-a dus, l-a întâmpinat la muntele lui Dumnezeu și l-a sărutat.", "Moise i-a spus lui Aaron toate cuvintele DOMNULUI, Care îl trimisese, și toate semnele pe care îi poruncise să le facă.", "Moise și Aaron au plecat și au strâns pe toți bătrânii fiilor lui Israel.", "Aaron a rostit toate cuvintele pe care DOMNUL i le spusese lui Moise și a făcut semnele înaintea poporului.", "Poporul a crezut. Când au auzit că DOMNUL luase seama la fiii lui Israel și văzuse suferința lor, s-au plecat și s-au închinat."],
    5: ["După aceea, Moise și Aaron s-au dus la Faraon și i-au zis: „Așa vorbește DOMNUL, Dumnezeul lui Israel: «Lasă pe poporul Meu să plece, ca să-Mi țină o sărbătoare în pustiu!»”", "Faraon a răspuns: „Cine este DOMNUL, ca să ascult de glasul Lui și să las pe Israel să plece? Nu-L cunosc pe DOMNUL și nu voi lăsa pe Israel să plece!”", "Ei au zis: „Dumnezeul evreilor ne-a întâmpinat. Lasă-ne, te rugăm, să mergem cale de trei zile în pustiu, ca să aducem jertfe DOMNULUI, Dumnezeul nostru, ca să nu ne lovească cu ciumă sau cu sabie!”", "Regele Egiptului le-a spus: „Moise și Aaron, de ce îi opriți pe oameni de la munca lor? Întoarceți-vă la poverile voastre!”", "Faraonul a mai spus: „Iată că poporul țării este acum numeros, iar voi îi faceți să se odihnească de munca lui!”", "În aceeași zi, faraonul le-a poruncit supraveghetorilor poporului și responsabililor dintre ei:", "„Să nu mai dați poporului paie ca mai înainte pentru facerea cărămizilor; să se ducă ei înșiși să-și strângă paie!", "Totuși, să le cereți același număr de cărămizi pe care le făceau mai înainte, fără să le scădeți nimic; căci sunt leneși, de aceea strigă și zic: «Haidem să aducem jertfe Dumnezeului nostru!»", "Să se apese munci grele peste oamenii aceștia, ca să aibă de lucru și să nu mai plece urechea la cuvinte amăgitoare!”", "Supraveghetorii poporului și responsabilii dintre ei au ieșit și le-au spus oamenilor: „Așa vorbește faraonul: «Nu vă mai dau paie.", "Duceți-vă voi înșiși și strângeți-vă paie de unde veți găsi; dar din munca voastră nu se scade nimic!»”", "Poporul s-a răspândit în toată țara Egiptului ca să strângă miriște în loc de paie.", "Supraveghetorii îi zoreau, spunând: „Îndepliniți-vă norma zilnică, la fel ca atunci când primeați paie!”", "Responsabilii dintre fiii lui Israel, pe care îi puseseră peste ei supraveghetorii faraonului, erau bătuți și întrebați: „De ce nu v-ați îndeplinit nici ieri, nici astăzi norma de cărămizi, ca mai înainte?”", "Responsabilii dintre fiii lui Israel au venit și au strigat către faraon: „De ce te porți astfel cu slujitorii tăi?", "Slujitorilor tăi nu li se mai dau paie, dar ni se spune: «Faceți cărămizi!» Iată că slujitorii tăi sunt bătuți, deși vina este a propriului tău popor.”", "Faraon a răspuns: „Sunteți leneși, leneși! De aceea ziceți: «Haidem să aducem jertfe DOMNULUI!»", "Acum duceți-vă și lucrați! Nu vi se vor da paie, dar veți preda același număr de cărămizi!”", "Responsabilii dintre fiii lui Israel au văzut că se aflau în mare strâmtorare când li s-a spus: „Să nu scădeți nimic din norma zilnică de cărămizi!”", "Ieșind de la Faraon, i-au întâlnit pe Moise și pe Aaron, care îi așteptau.", "Ei le-au spus: „DOMNUL să vă vadă și să judece! Ne-ați făcut respingători în ochii faraonului și ai slujitorilor lui și le-ați pus sabia în mână ca să ne omoare!”", "Moise s-a întors la DOMNUL și a spus: „Doamne, de ce ai adus necaz asupra acestui popor? De ce m-ai trimis?", "De când m-am dus la Faraon ca să-i vorbesc în Numele Tău, el face rău acestui popor, și Tu n-ai izbăvit nicidecum pe poporul Tău!”"],
    6: ["DOMNUL i-a spus lui Moise: „Acum vei vedea ce îi voi face faraonului: silit de o mână puternică îi va lăsa să plece și, silit de o mână puternică, îi va izgoni din țara lui.”", "Dumnezeu i-a vorbit lui Moise și i-a spus: „Eu sunt DOMNUL.", "M-am arătat lui Avraam, lui Isaac și lui Iacov ca Dumnezeul Atotputernic, dar prin Numele Meu, DOMNUL, nu M-am făcut cunoscut lor.", "Am încheiat legământul Meu cu ei, ca să le dau țara Canaanului, țara în care au locuit ca străini.", "Am auzit și gemetele fiilor lui Israel, pe care egiptenii îi țin în robie, și Mi-am adus aminte de legământul Meu.", "De aceea spune-le fiilor lui Israel: «Eu sunt DOMNUL. Vă voi scoate de sub poverile egiptenilor, vă voi elibera din robia lor și vă voi răscumpăra cu braț întins și prin judecăți mari.", "Vă voi lua ca popor al Meu și voi fi Dumnezeul vostru. Veți ști că Eu sunt DOMNUL, Dumnezeul vostru, Cel care vă scoate de sub poverile egiptenilor.", "Vă voi aduce în țara pe care am jurat că o voi da lui Avraam, lui Isaac și lui Iacov și v-o voi da ca moștenire. Eu sunt DOMNUL.»”", "Moise le-a spus aceste lucruri fiilor lui Israel, dar ei nu l-au ascultat din cauza descurajării și a robiei aspre.", "DOMNUL i-a vorbit lui Moise și i-a spus:", "„Du-te și vorbește-i faraonului, regele Egiptului, ca să-i lase pe fiii lui Israel să plece din țara lui.”", "Moise a spus înaintea DOMNULUI: „Iată, fiii lui Israel nu m-au ascultat. Cum mă va asculta faraonul, când eu am buze necircumcise?”", "DOMNUL le-a vorbit lui Moise și lui Aaron și le-a dat porunci cu privire la fiii lui Israel și la faraon, regele Egiptului, ca să-i scoată pe fiii lui Israel din țara Egiptului.", "Acestea sunt căpeteniile caselor părinților lor. Fiii lui Ruben, întâiul născut al lui Israel, au fost Hanoch, Pallu, Hețron și Carmi. Acestea sunt familiile lui Ruben.", "Fiii lui Simeon au fost Iemuel, Iamin, Ohad, Iachin, Țohar și Șaul, fiul unei femei canaanite. Acestea sunt familiile lui Simeon.", "Acestea sunt numele fiilor lui Levi, după generațiile lor: Gherșon, Chehat și Merari. Levi a trăit o sută treizeci și șapte de ani.", "Fiii lui Gherșon au fost Libni și Șimei, după familiile lor.", "Fiii lui Chehat au fost Amram, Ițhar, Hebron și Uziel. Chehat a trăit o sută treizeci și trei de ani.", "Fiii lui Merari au fost Mahli și Muși. Acestea sunt familiile leviților, după generațiile lor.", "Amram a luat-o de soție pe Iochebed, mătușa sa, iar ea i-a născut pe Aaron și pe Moise. Amram a trăit o sută treizeci și șapte de ani.", "Fiii lui Ițhar au fost Core, Nefeg și Zicri.", "Fiii lui Uziel au fost Mișael, Elțafan și Sitri.", "Aaron a luat-o de soție pe Elișeba, fiica lui Aminadab și sora lui Nahșon, iar ea i-a născut pe Nadab, Abihu, Eleazar și Itamar.", "Fiii lui Core au fost Asir, Elcana și Abiasaf. Acestea sunt familiile coriților.", "Eleazar, fiul lui Aaron, a luat-o de soție pe una dintre fiicele lui Putiel, iar ea i l-a născut pe Fineas. Acestea sunt căpeteniile caselor părintești ale leviților, după familiile lor.", "Aceștia sunt Aaron și Moise cărora DOMNUL le-a spus: „Scoateți-i pe fiii lui Israel din țara Egiptului, după oștirile lor.”", "Ei sunt cei care i-au vorbit faraonului, regele Egiptului, ca să-i scoată pe fiii lui Israel din Egipt. Aceștia sunt Moise și Aaron.", "În ziua în care DOMNUL i-a vorbit lui Moise în țara Egiptului,", "DOMNUL i-a spus lui Moise: „Eu sunt DOMNUL. Spune-i faraonului, regele Egiptului, tot ce îți spun.”", "Dar Moise a spus înaintea DOMNULUI: „Iată, eu am buze necircumcise. Cum mă va asculta faraonul?”"],
    7: ["DOMNUL i-a spus lui Moise: „Iată, te-am făcut ca Dumnezeu pentru faraon, iar Aaron, fratele tău, va fi profetul tău.", "Tu vei spune tot ce îți poruncesc, iar Aaron, fratele tău, îi va vorbi faraonului, ca să-i lase pe fiii lui Israel să plece din țara lui.", "Eu voi împietri inima faraonului și Îmi voi înmulți semnele și minunile în țara Egiptului.", "Faraonul nu vă va asculta. Atunci Îmi voi pune mâna asupra Egiptului și, prin judecăți mari, Îmi voi scoate oștirile, poporul Meu, pe fiii lui Israel, din țara Egiptului.", "Egiptenii vor ști că Eu sunt DOMNUL când Îmi voi întinde mâna asupra Egiptului și îi voi scoate pe fiii lui Israel din mijlocul lor.”", "Moise și Aaron au făcut întocmai; au făcut așa cum le poruncise DOMNUL.", "Moise avea optzeci de ani, iar Aaron optzeci și trei de ani când i-au vorbit faraonului.", "DOMNUL le-a vorbit lui Moise și lui Aaron și le-a spus:", "„Când faraonul vă va spune: «Faceți o minune!», să-i spui lui Aaron: «Ia-ți toiagul și aruncă-l înaintea faraonului; el se va preface într-un șarpe.»”", "Moise și Aaron au intrat la faraon și au făcut așa cum le poruncise DOMNUL. Aaron și-a aruncat toiagul înaintea faraonului și a slujitorilor lui, iar acesta s-a prefăcut într-un șarpe.", "Atunci faraonul i-a chemat și pe înțelepți și pe vrăjitori, iar magicienii Egiptului au făcut și ei același lucru prin practicile lor tainice.", "Fiecare și-a aruncat toiagul, iar acestea s-au prefăcut în șerpi. Dar toiagul lui Aaron le-a înghițit toiagurile.", "Inima faraonului s-a împietrit și nu i-a ascultat, așa cum spusese DOMNUL.", "DOMNUL i-a spus lui Moise: „Inima faraonului este încăpățânată; el refuză să lase poporul să plece.", "Du-te la faraon dimineața, când va ieși la apă. Stai înaintea lui pe malul Nilului și ia în mână toiagul care se prefăcuse în șarpe.", "Spune-i: «DOMNUL, Dumnezeul evreilor, m-a trimis la tine și ți-a spus: Lasă poporul Meu să plece ca să-Mi slujească în pustiu. Dar până acum nu ai ascultat.", "Așa vorbește DOMNUL: Prin aceasta vei ști că Eu sunt DOMNUL. Iată, voi lovi cu toiagul din mâna mea apele Nilului, iar ele se vor preface în sânge.", "Peștii din Nil vor muri, Nilul va mirosi urât, iar egiptenilor le va fi scârbă să bea apă din el.»”", "DOMNUL i-a spus lui Moise: „Spune-i lui Aaron: «Ia-ți toiagul și întinde-ți mâna peste apele Egiptului, peste râurile, canalele, iazurile și toate rezervoarele lor, ca să se prefacă în sânge. Va fi sânge în toată țara Egiptului, chiar și în vasele de lemn și de piatră.»”", "Moise și Aaron au făcut așa cum le poruncise DOMNUL. Aaron și-a ridicat toiagul și a lovit apele Nilului înaintea faraonului și a slujitorilor lui, iar toate apele Nilului s-au prefăcut în sânge.", "Peștii din Nil au murit, Nilul a început să miroasă urât, iar egiptenii nu au mai putut bea apă din el. Sângele era în toată țara Egiptului.", "Magicienii Egiptului au făcut și ei același lucru prin practicile lor tainice. Inima faraonului s-a împietrit și nu i-a ascultat, așa cum spusese DOMNUL.", "Faraonul s-a întors și a intrat în casa lui, fără să ia la inimă nici acest lucru.", "Toți egiptenii au săpat în jurul Nilului ca să găsească apă de băut, fiindcă nu puteau bea din apa Nilului.", "Au trecut șapte zile după ce DOMNUL lovise Nilul."],
    8: ["DOMNUL i-a vorbit lui Moise: „Du-te la faraon și spune-i: «Așa vorbește DOMNUL: Lasă poporul Meu să plece ca să-Mi slujească.", "Dacă refuzi să-l lași să plece, voi lovi întregul tău ținut cu broaște.", "Nilul va mișuna de broaște. Ele se vor urca și vor intra în casa ta, în dormitorul tău și în patul tău, în casele slujitorilor tăi și peste poporul tău, în cuptoarele și în covatele tale de frământat.", "Broaștele se vor urca peste tine, peste poporul tău și peste toți slujitorii tăi.»”", "DOMNUL i-a spus lui Moise: „Spune-i lui Aaron: «Întinde-ți mâna cu toiagul peste râuri, peste canale și peste iazuri și fă să se urce broaște peste țara Egiptului.»”", "Aaron și-a întins mâna peste apele Egiptului, iar broaștele s-au urcat și au acoperit țara Egiptului.", "Magicienii au făcut și ei la fel prin practicile lor tainice și au făcut să se urce broaște peste țara Egiptului.", "Atunci faraonul i-a chemat pe Moise și pe Aaron și le-a spus: „Rugați-L pe DOMNUL să îndepărteze broaștele de la mine și de la poporul meu, iar eu voi lăsa poporul să plece ca să aducă jertfe DOMNULUI.”", "Moise i-a spus faraonului: „Hotărăște tu când să mă rog pentru tine, pentru slujitorii tăi și pentru poporul tău, ca broaștele să fie nimicite din casele voastre și să rămână numai în Nil.”", "El a răspuns: „Mâine.” Moise a spus: „Va fi după cuvântul tău, ca să știi că nu este nimeni ca DOMNUL, Dumnezeul nostru.", "Broaștele se vor îndepărta de la tine, din casele tale, de la slujitorii tăi și de la poporul tău și vor rămâne numai în Nil.”", "Moise și Aaron au ieșit de la faraon, iar Moise a strigat către DOMNUL cu privire la broaștele pe care le adusese asupra faraonului.", "DOMNUL a făcut după cuvântul lui Moise, iar broaștele au murit în case, în curți și pe câmpuri.", "Le-au strâns în grămezi, iar țara a început să miroasă urât.", "Când faraonul a văzut că avea răgaz, și-a împietrit inima și nu i-a ascultat, așa cum spusese DOMNUL.", "DOMNUL i-a spus lui Moise: „Spune-i lui Aaron: «Întinde-ți toiagul și lovește țărâna pământului, ca ea să se prefacă în țânțari în toată țara Egiptului.»”", "Ei au făcut așa. Aaron și-a întins mâna cu toiagul, a lovit țărâna pământului, iar țânțarii au venit peste oameni și peste animale. Toată țărâna pământului s-a prefăcut în țânțari în toată țara Egiptului.", "Magicienii au încercat să facă și ei țânțari prin practicile lor tainice, dar nu au putut. Țânțarii erau pe oameni și pe animale.", "Atunci magicienii i-au spus faraonului: „Acesta este degetul lui Dumnezeu!” Dar inima faraonului s-a împietrit și nu i-a ascultat, așa cum spusese DOMNUL.", "DOMNUL i-a spus lui Moise: „Scoală-te dis-de-dimineață, înfățișează-te înaintea faraonului când va ieși la apă și spune-i: «Așa vorbește DOMNUL: Lasă poporul Meu să plece ca să-Mi slujească.", "Dacă nu vei lăsa poporul Meu să plece, voi trimite roiuri de insecte peste tine, peste slujitorii tăi, peste poporul tău și în casele tale. Casele egiptenilor și chiar pământul pe care stau se vor umple de roiuri.", "În ziua aceea voi pune deoparte ținutul Goșen, unde locuiește poporul Meu, și acolo nu vor fi roiuri, ca să știi că Eu, DOMNUL, sunt în mijlocul țării.", "Voi face o deosebire între poporul Meu și poporul tău. Semnul acesta va avea loc mâine.»”", "DOMNUL a făcut astfel. Roiuri grele de insecte au intrat în casa faraonului, în casele slujitorilor lui și în toată țara Egiptului. Țara a fost pustiită de roiuri.", "Faraonul i-a chemat pe Moise și pe Aaron și le-a spus: „Duceți-vă și aduceți jertfe Dumnezeului vostru aici, în țară!”", "Moise a răspuns: „Nu este potrivit să facem așa, fiindcă jertfele pe care le aducem DOMNULUI, Dumnezeul nostru, sunt detestabile pentru egipteni. Dacă aducem înaintea ochilor lor jertfe pe care le consideră detestabile, nu ne vor ucide cu pietre?", "Vom merge cale de trei zile în pustiu și vom aduce jertfe DOMNULUI, Dumnezeul nostru, așa cum ne va porunci.”", "Faraonul a spus: „Vă voi lăsa să plecați ca să aduceți jertfe DOMNULUI, Dumnezeul vostru, în pustiu, numai să nu mergeți prea departe. Rugați-vă pentru mine!”", "Moise a spus: „Iată, voi ieși de la tine și mă voi ruga DOMNULUI. Mâine, roiurile se vor îndepărta de la faraon, de la slujitorii lui și de la poporul lui. Dar faraonul să nu ne mai înșele, refuzând să lase poporul să plece ca să aducă jertfe DOMNULUI.”", "Moise a ieșit de la faraon și s-a rugat DOMNULUI.", "DOMNUL a făcut după cuvântul lui Moise și a îndepărtat roiurile de la faraon, de la slujitorii lui și de la poporul lui; nu a mai rămas niciunul.", "Dar faraonul și-a împietrit inima și de data aceasta și nu a lăsat poporul să plece."],
    9: ["Atunci DOMNUL i-a spus lui Moise: „Du-te la faraon și spune-i: «Așa vorbește DOMNUL, Dumnezeul evreilor: Lasă poporul Meu să plece ca să-Mi slujească.", "Dacă refuzi să-l lași să plece și continui să-l ții,", "iată, mâna DOMNULUI va veni peste animalele tale de pe câmp — peste cai, măgari, cămile, cirezi și turme — printr-o ciumă foarte grea.", "DOMNUL va face deosebire între animalele lui Israel și animalele Egiptului și nu va muri nimic din tot ce le aparține fiilor lui Israel.»”", "DOMNUL a hotărât timpul și a spus: „Mâine va face DOMNUL acest lucru în țară.”", "A doua zi, DOMNUL a făcut acel lucru. Animalele egiptenilor au murit, dar dintre animalele fiilor lui Israel nu a murit niciunul.", "Faraonul a trimis să cerceteze și iată că dintre animalele israeliților nu murise niciunul. Dar inima faraonului a rămas încăpățânată și nu a lăsat poporul să plece.", "DOMNUL le-a spus lui Moise și lui Aaron: „Luați câte un pumn de cenușă din cuptor, iar Moise să o arunce spre cer înaintea faraonului.", "Ea se va preface într-un praf fin peste toată țara Egiptului și va provoca pe oameni și pe animale bube care se transformă în bășici, în toată țara Egiptului.”", "Ei au luat cenușă din cuptor și s-au înfățișat înaintea faraonului. Moise a aruncat-o spre cer, iar ea a provocat pe oameni și pe animale bube care se transformau în bășici.", "Magicienii nu au putut sta înaintea lui Moise din cauza bubelor, fiindcă bubele erau pe magicieni și pe toți egiptenii.", "DOMNUL a împietrit inima faraonului și el nu i-a ascultat, așa cum îi spusese DOMNUL lui Moise.", "DOMNUL i-a spus lui Moise: „Scoală-te dis-de-dimineață, înfățișează-te înaintea faraonului și spune-i: «Așa vorbește DOMNUL, Dumnezeul evreilor: Lasă poporul Meu să plece ca să-Mi slujească.", "De data aceasta voi trimite toate loviturile Mele asupra inimii tale, asupra slujitorilor tăi și asupra poporului tău, ca să știi că nu este nimeni ca Mine pe tot pământul.", "Dacă Mi-aș fi întins până acum mâna și te-aș fi lovit pe tine și pe poporul tău cu ciumă, ai fi fost șters de pe pământ.", "Dar tocmai pentru aceasta te-am lăsat în picioare: ca să-ți arăt puterea Mea și Numele Meu să fie vestit pe tot pământul.", "Tu încă te înalți împotriva poporului Meu și nu-l lași să plece.", "Iată, mâine, pe vremea aceasta, voi face să cadă o grindină foarte grea, cum nu a mai fost în Egipt din ziua întemeierii lui și până acum.", "Acum trimite să fie adăpostite animalele tale și tot ce ai pe câmp. Grindina va cădea peste orice om și orice animal care va fi găsit pe câmp și nu va fi adus înăuntru, iar ei vor muri.»”", "Aceia dintre slujitorii faraonului care s-au temut de cuvântul DOMNULUI și-au adus în grabă slujitorii și animalele în case.", "Dar cei care nu au luat în serios cuvântul DOMNULUI și-au lăsat slujitorii și animalele pe câmp.", "DOMNUL i-a spus lui Moise: „Întinde-ți mâna spre cer, ca să cadă grindină în toată țara Egiptului, peste oameni, peste animale și peste toate plantele câmpului.”", "Moise și-a întins toiagul spre cer, iar DOMNUL a trimis tunete și grindină și a făcut să cadă foc pe pământ. DOMNUL a făcut să plouă cu grindină peste țara Egiptului.", "A fost grindină foarte grea, cu foc fulgerând în mijlocul grindinii, cum nu mai fusese în toată țara Egiptului de când devenise un popor.", "Grindina a lovit în toată țara Egiptului tot ce era pe câmp, atât oameni, cât și animale. A lovit toate plantele câmpului și a sfărâmat toți copacii de pe câmp.", "Numai în ținutul Goșen, unde erau fiii lui Israel, nu a fost grindină.", "Faraonul a trimis să-i cheme pe Moise și pe Aaron și le-a spus: „De data aceasta am păcătuit. DOMNUL este drept, iar eu și poporul meu suntem vinovați.", "Rugați-vă DOMNULUI! Sunt destule tunetele lui Dumnezeu și grindina. Vă voi lăsa să plecați și nu veți mai rămâne.”", "Moise i-a spus: „Când voi ieși din cetate, îmi voi întinde mâinile spre DOMNUL. Tunetele vor înceta și nu va mai fi grindină, ca să știi că pământul este al DOMNULUI.", "Dar știu că tu și slujitorii tăi încă nu vă temeți de DOMNUL Dumnezeu.”", "Inul și orzul fuseseră lovite, fiindcă orzul era în spic, iar inul era în floare.", "Dar grâul și alacul nu fuseseră lovite, pentru că se coc mai târziu.", "Moise a ieșit din cetate de la faraon și și-a întins mâinile spre DOMNUL. Tunetele și grindina au încetat, iar ploaia nu s-a mai revărsat pe pământ.", "Când faraonul a văzut că ploaia, grindina și tunetele încetaseră, a păcătuit din nou și și-a împietrit inima, el și slujitorii lui.", "Inima faraonului s-a împietrit și nu i-a lăsat pe fiii lui Israel să plece, așa cum spusese DOMNUL prin Moise."],
    10: ["DOMNUL i-a spus lui Moise: „Du-te la faraon, căci i-am împietrit inima lui și inimile slujitorilor lui, ca să pun aceste semne ale Mele în mijlocul lor", "și ca tu să povestești fiului tău și fiului fiului tău cum am lucrat împotriva Egiptului și ce semne am făcut în mijlocul lor, ca să știți că Eu sunt DOMNUL.”", "Moise și Aaron au intrat la faraon și i-au spus: „Așa vorbește DOMNUL, Dumnezeul evreilor: «Până când vei refuza să te smerești înaintea Mea? Lasă poporul Meu să plece ca să-Mi slujească.", "Dacă refuzi să lași poporul Meu să plece, iată, mâine voi aduce lăcuste în ținutul tău.", "Ele vor acoperi fața pământului, astfel încât pământul nu va mai putea fi văzut. Vor mânca ce a scăpat și v-a rămas după grindină și vor mânca orice copac care crește pe câmpurile voastre.", "Casele tale, casele tuturor slujitorilor tăi și casele tuturor egiptenilor se vor umple de ele, cum nu au văzut părinții și strămoșii tăi din ziua în care au fost pe pământ și până astăzi.»” Apoi Moise s-a întors și a ieșit de la faraon.", "Slujitorii faraonului i-au spus: „Până când va fi omul acesta o cursă pentru noi? Lasă-i pe bărbați să plece ca să-I slujească DOMNULUI, Dumnezeul lor. Încă nu înțelegi că Egiptul este distrus?”", "Moise și Aaron au fost aduși din nou la faraon, iar el le-a spus: „Duceți-vă și slujiți-I DOMNULUI, Dumnezeul vostru. Dar cine anume va merge?”", "Moise a răspuns: „Vom merge cu tinerii și cu bătrânii noștri, cu fiii și cu fiicele noastre, cu turmele și cu cirezile noastre, fiindcă avem de ținut o sărbătoare pentru DOMNUL.”", "Faraonul le-a spus: „Așa să fie DOMNUL cu voi cum vă voi lăsa eu să plecați împreună cu copiii voștri! Este limpede că aveți intenții rele.", "Nu! Mergeți acum numai voi, bărbații, și slujiți-I DOMNULUI, fiindcă aceasta ați cerut.” Apoi au fost izgoniți dinaintea faraonului.", "DOMNUL i-a spus lui Moise: „Întinde-ți mâna peste țara Egiptului ca să vină lăcustele peste ea și să mănânce toate plantele țării, tot ce a lăsat grindina.”", "Moise și-a întins toiagul peste țara Egiptului, iar DOMNUL a adus peste țară un vânt de răsărit toată ziua aceea și toată noaptea. Dimineața, vântul de răsărit adusese lăcustele.", "Lăcustele s-au ridicat peste toată țara Egiptului și s-au așezat în tot ținutul Egiptului. Erau nespus de multe; înaintea lor nu mai fuseseră asemenea lăcuste și nici după ele nu vor mai fi.", "Au acoperit fața întregului pământ, încât țara s-a întunecat. Au mâncat toate plantele țării și toate roadele copacilor pe care le lăsase grindina. Nu a mai rămas nimic verde, nici copac, nici plantă a câmpului, în toată țara Egiptului.", "Faraonul i-a chemat în grabă pe Moise și pe Aaron și le-a spus: „Am păcătuit împotriva DOMNULUI, Dumnezeul vostru, și împotriva voastră.", "Acum, te rog, iartă-mi păcatul încă o dată și rugați-L pe DOMNUL, Dumnezeul vostru, să îndepărteze de la mine această moarte.”", "Moise a ieșit de la faraon și s-a rugat DOMNULUI.", "DOMNUL a făcut să sufle un vânt foarte puternic dinspre apus, care a ridicat lăcustele și le-a aruncat în Marea Roșie. Nu a mai rămas nicio lăcustă în tot ținutul Egiptului.", "Dar DOMNUL a împietrit inima faraonului, iar el nu i-a lăsat pe fiii lui Israel să plece.", "DOMNUL i-a spus lui Moise: „Întinde-ți mâna spre cer, ca peste țara Egiptului să vină un întuneric atât de gros, încât să poată fi pipăit.”", "Moise și-a întins mâna spre cer, iar peste toată țara Egiptului a fost întuneric gros timp de trei zile.", "Oamenii nu se vedeau unii pe alții și nimeni nu s-a ridicat din locul său timp de trei zile. Dar toți fiii lui Israel aveau lumină în locuințele lor.", "Faraonul l-a chemat pe Moise și i-a spus: „Duceți-vă și slujiți-I DOMNULUI! Numai turmele și cirezile voastre să rămână; chiar și copiii voștri pot merge cu voi.”", "Moise a răspuns: „Tu însuți trebuie să ne dai animale pentru jertfe și arderi-de-tot, ca să le aducem DOMNULUI, Dumnezeul nostru.", "Și animalele noastre vor merge cu noi; nu va rămâne nici măcar o copită, fiindcă din ele vom lua ca să-I slujim DOMNULUI, Dumnezeul nostru. Până nu ajungem acolo, nu știm cu ce Îi vom sluji DOMNULUI.”", "Dar DOMNUL a împietrit inima faraonului și el nu a vrut să-i lase să plece.", "Faraonul i-a spus: „Pleacă de la mine! Ai grijă să nu-mi mai vezi fața, căci în ziua în care îmi vei vedea fața vei muri!”", "Moise a răspuns: „Ai vorbit bine. Nu-ți voi mai vedea fața.”"],
    11: ["DOMNUL i-a spus lui Moise: „Voi mai aduce o singură lovitură asupra faraonului și asupra Egiptului. După aceea vă va lăsa să plecați de aici. Când vă va lăsa să plecați, vă va izgoni cu totul de aici.", "Vorbește acum poporului: fiecare bărbat să ceară de la vecinul său, iar fiecare femeie de la vecina sa obiecte de argint și obiecte de aur.”", "DOMNUL a făcut ca poporul să găsească bunăvoință în ochii egiptenilor. Mai mult, Moise era foarte respectat în țara Egiptului, atât de slujitorii faraonului, cât și de popor.", "Moise a spus: „Așa vorbește DOMNUL: «Pe la miezul nopții voi trece prin mijlocul Egiptului.", "Toți întâii născuți din țara Egiptului vor muri, de la întâiul născut al faraonului, care stă pe tronul său, până la întâiul născut al slujitoarei aflate în spatele râșniței, precum și toți întâii născuți ai animalelor.", "În toată țara Egiptului va fi un strigăt atât de mare cum nu a mai fost și nu va mai fi.", "Dar împotriva niciunuia dintre fiii lui Israel, fie om, fie animal, nici măcar un câine nu-și va mișca limba, ca să știți că DOMNUL face deosebire între Egipt și Israel.»", "Toți acești slujitori ai tăi vor coborî la mine, se vor pleca înaintea mea și vor spune: «Pleacă, tu și tot poporul care te urmează!» După aceea voi pleca.” Apoi Moise a ieșit de la faraon aprins de mânie.", "DOMNUL îi spusese lui Moise: „Faraonul nu vă va asculta, pentru ca minunile Mele să se înmulțească în țara Egiptului.”", "Moise și Aaron au făcut toate aceste minuni înaintea faraonului, dar DOMNUL a împietrit inima faraonului, iar el nu i-a lăsat pe fiii lui Israel să plece din țara lui."],
    12: ["DOMNUL le-a vorbit lui Moise și lui Aaron în țara Egiptului și le-a spus:", "„Luna aceasta să fie pentru voi începutul lunilor; să fie pentru voi prima lună a anului.", "Vorbiți întregii adunări a lui Israel și spuneți-le: «În ziua a zecea a acestei luni, fiecare bărbat să ia un animal din turmă pentru casa părintească, câte unul pentru fiecare gospodărie.", "Dacă gospodăria este prea mică pentru un animal întreg, să-l ia împreună cu vecinul cel mai apropiat, după numărul persoanelor. Să calculați pentru fiecare animal cât poate mânca fiecare om.", "Animalul să fie fără cusur, de parte bărbătească și de un an. Îl puteți lua dintre oi sau dintre capre.", "Să-l păstrați până în ziua a paisprezecea a acestei luni, iar întreaga adunare a comunității lui Israel să-l înjunghie spre seară.", "Să ia din sânge și să pună pe cei doi ușori ai ușii și pe pragul de sus al caselor în care îl vor mânca.", "În noaptea aceea să mănânce carnea friptă la foc, împreună cu azime și ierburi amare.", "Să nu mâncați nimic din el crud sau fiert în apă, ci fript la foc, cu capul, picioarele și măruntaiele lui.", "Să nu lăsați nimic din el până dimineața. Ce va rămâne până dimineața să ardeți în foc.", "Să-l mâncați astfel: cu brâul strâns la mijloc, cu sandalele în picioare și cu toiagul în mână. Să-l mâncați în grabă; este Paștele DOMNULUI.", "În noaptea aceea voi trece prin țara Egiptului și voi lovi pe toți întâii născuți din țara Egiptului, atât dintre oameni, cât și dintre animale. Voi aduce judecăți împotriva tuturor dumnezeilor Egiptului. Eu sunt DOMNUL.", "Sângele va fi pentru voi un semn pe casele în care vă aflați. Când voi vedea sângele, voi trece pe lângă voi și nu va veni peste voi nicio lovitură nimicitoare când voi lovi țara Egiptului.", "Ziua aceasta să fie pentru voi o aducere-aminte. Să o sărbătoriți ca sărbătoare pentru DOMNUL, din generație în generație; să o sărbătoriți printr-o rânduială veșnică.", "Timp de șapte zile să mâncați azime. Chiar din prima zi să îndepărtați aluatul dospit din casele voastre, căci oricine va mânca pâine dospită din prima zi până în ziua a șaptea va fi îndepărtat din Israel.", "În prima zi să aveți o adunare sfântă și în ziua a șaptea o adunare sfântă. Să nu faceți nicio muncă în aceste zile, în afară de pregătirea hranei necesare fiecărei persoane.", "Să păziți Sărbătoarea Azimelor, căci chiar în ziua aceasta am scos oștirile voastre din țara Egiptului. Să păziți ziua aceasta din generație în generație, printr-o rânduială veșnică.", "În prima lună, din seara zilei a paisprezecea până în seara zilei a douăzeci și una, să mâncați azime.", "Timp de șapte zile să nu se găsească aluat dospit în casele voastre. Oricine va mânca ceva dospit va fi îndepărtat din comunitatea lui Israel, fie străin, fie născut în țară.", "Să nu mâncați nimic dospit. În toate locuințele voastre să mâncați azime.»”", "Moise i-a chemat pe toți bătrânii lui Israel și le-a spus: „Mergeți, luați-vă animale din turmă pentru familiile voastre și înjunghiați jertfa de Paște.", "Luați un mănunchi de isop, înmuiați-l în sângele din vas și atingeți cu sângele din vas pragul de sus și cei doi ușori ai ușii. Niciunul dintre voi să nu iasă pe ușa casei sale până dimineața.", "Când DOMNUL va trece ca să-i lovească pe egipteni și va vedea sângele pe pragul de sus și pe cei doi ușori, DOMNUL va trece peste intrare și nu-i va permite nimicitorului să intre în casele voastre ca să vă lovească.", "Să păziți acest lucru ca rânduială pentru voi și pentru fiii voștri pentru totdeauna.", "Când veți intra în țara pe care DOMNUL v-o va da, așa cum a promis, să păstrați această slujire.", "Când copiii voștri vă vor întreba: «Ce înseamnă pentru voi această slujire?»,", "să le răspundeți: «Este jertfa de Paște pentru DOMNUL, Care a trecut peste casele fiilor lui Israel în Egipt, când i-a lovit pe egipteni, dar casele noastre le-a cruțat.»” Poporul s-a plecat și s-a închinat.", "Fiii lui Israel au mers și au făcut întocmai; au făcut așa cum le poruncise DOMNUL lui Moise și lui Aaron.", "La miezul nopții, DOMNUL i-a lovit pe toți întâii născuți din țara Egiptului, de la întâiul născut al faraonului, care stătea pe tronul său, până la întâiul născut al prizonierului aflat în temniță, precum și pe toți întâii născuți ai animalelor.", "Faraonul s-a ridicat în timpul nopții, el, toți slujitorii lui și toți egiptenii. În Egipt a fost un strigăt mare, căci nu era casă în care să nu fie cineva mort.", "Faraonul i-a chemat noaptea pe Moise și pe Aaron și le-a spus: „Ridicați-vă și plecați din mijlocul poporului meu, atât voi, cât și fiii lui Israel! Mergeți și slujiți-I DOMNULUI, așa cum ați spus.", "Luați-vă și turmele și cirezile, așa cum ați spus, și plecați! Binecuvântați-mă și pe mine.”", "Egiptenii îi zoreau pe oameni ca să-i scoată repede din țară, căci spuneau: „Vom muri cu toții!”", "Poporul și-a luat aluatul înainte să dospească, purtându-și covatele de frământat învelite în haine, pe umeri.", "Fiii lui Israel au făcut după cuvântul lui Moise și au cerut de la egipteni obiecte de argint, obiecte de aur și haine.", "DOMNUL a făcut ca poporul să găsească bunăvoință în ochii egiptenilor, iar aceștia le-au dat ceea ce au cerut. Astfel au luat prada Egiptului.", "Fiii lui Israel au pornit din Ramses spre Sucot. Erau aproximativ șase sute de mii de bărbați care mergeau pe jos, în afară de copii.", "Împreună cu ei a urcat și o mulțime amestecată, precum și turme și cirezi, foarte multe animale.", "Au copt turte nedospite din aluatul pe care îl scoseseră din Egipt. Aluatul nu dospise, fiindcă fuseseră izgoniți din Egipt și nu putuseră aștepta; nici nu-și pregătiseră provizii pentru drum.", "Timpul cât au locuit fiii lui Israel în Egipt a fost de patru sute treizeci de ani.", "La sfârșitul celor patru sute treizeci de ani, chiar în ziua aceea, toate oștirile DOMNULUI au ieșit din țara Egiptului.", "A fost o noapte de veghe pentru DOMNUL, când i-a scos din țara Egiptului. Aceasta este noaptea DOMNULUI, noapte de veghe pentru toți fiii lui Israel, din generație în generație.", "DOMNUL le-a spus lui Moise și lui Aaron: „Aceasta este rânduiala Paștelui: niciun străin din afară să nu mănânce din el.", "Orice sclav cumpărat cu argint va putea mânca din el după ce îl vei circumcide.", "Străinul aflat temporar și lucrătorul angajat să nu mănânce din el.", "Să fie mâncat într-o singură casă. Să nu scoateți nimic din carne afară din casă și să nu-i zdrobiți niciun os.", "Întreaga comunitate a lui Israel să țină Paștele.", "Dacă un străin care locuiește printre voi vrea să țină Paștele pentru DOMNUL, toți cei de parte bărbătească din casa lui să fie circumciși. Atunci se va putea apropia și îl va putea ține și va fi ca unul născut în țară. Dar nicio persoană necircumcisă să nu mănânce din el.", "Aceeași lege să fie pentru cel născut în țară și pentru străinul care locuiește printre voi.”", "Toți fiii lui Israel au făcut întocmai; au făcut așa cum le poruncise DOMNUL lui Moise și lui Aaron.", "Chiar în ziua aceea, DOMNUL i-a scos pe fiii lui Israel din țara Egiptului, după oștirile lor."],
    13: ["DOMNUL i-a vorbit lui Moise și i-a spus:", "„Pune-Mi deoparte orice întâi născut, orice întâi venit care deschide pântecele printre fiii lui Israel, atât dintre oameni, cât și dintre animale. Este al Meu.”", "Moise a spus poporului: „Aduceți-vă aminte de ziua aceasta, în care ați ieșit din Egipt, din casa robiei, căci prin puterea mâinii Sale v-a scos DOMNUL de aici. Să nu se mănânce pâine dospită.", "Astăzi ieșiți, în luna Abib.", "Când DOMNUL te va aduce în țara canaaniților, hetiților, amoriților, heviților și iebusiților, țară pe care a jurat părinților tăi că ți-o va da, o țară în care curge lapte și miere, să ții această slujire în luna aceasta.", "Timp de șapte zile să mănânci azime, iar în ziua a șaptea să fie o sărbătoare pentru DOMNUL.", "Azime să se mănânce în cele șapte zile. Să nu se vadă la tine pâine dospită și să nu se vadă la tine aluat dospit în tot ținutul tău.", "În ziua aceea să-i spui fiului tău: «Aceasta este din cauza a ceea ce a făcut DOMNUL pentru mine când am ieșit din Egipt.»", "Să fie pentru tine ca un semn pe mâna ta și ca o aducere-aminte între ochii tăi, pentru ca Legea DOMNULUI să fie în gura ta, căci cu mână puternică te-a scos DOMNUL din Egipt.", "Să păzești această rânduială la timpul ei, an de an.", "Când DOMNUL te va aduce în țara canaaniților, așa cum ți-a jurat ție și părinților tăi, și ți-o va da,", "să-I pui deoparte DOMNULUI orice întâi venit care deschide pântecele și orice întâi născut de parte bărbătească al animalelor tale; aceștia sunt ai DOMNULUI.", "Orice întâi născut al măgăriței să-l răscumperi cu un animal din turmă, iar dacă nu-l răscumperi, să-i frângi gâtul. Să răscumperi orice întâi născut dintre fiii tăi.", "Când fiul tău te va întreba în viitor: «Ce înseamnă aceasta?», să-i răspunzi: «Prin puterea mâinii Sale ne-a scos DOMNUL din Egipt, din casa robiei.", "Când faraonul s-a încăpățânat să nu ne lase să plecăm, DOMNUL i-a omorât pe toți întâii născuți din țara Egiptului, atât pe întâii născuți dintre oameni, cât și pe întâii născuți ai animalelor. De aceea Îi aduc jertfă DOMNULUI pe orice întâi venit de parte bărbătească care deschide pântecele, dar pe orice întâi născut dintre fiii mei îl răscumpăr.»", "Aceasta să fie ca un semn pe mâna ta și ca un simbol între ochii tăi, căci cu mână puternică ne-a scos DOMNUL din Egipt.”", "Când faraonul a lăsat poporul să plece, Dumnezeu nu l-a condus pe drumul țării filistenilor, deși era aproape, căci Dumnezeu a spus: „Nu cumva poporul să se răzgândească atunci când va vedea războiul și să se întoarcă în Egipt.”", "Dumnezeu a făcut poporul să ocolească pe drumul pustiei, spre Marea Roșie. Fiii lui Israel au ieșit din țara Egiptului în formație organizată.", "Moise a luat cu el oasele lui Iosif, căci Iosif îi pusese pe fiii lui Israel să jure, spunând: „Dumnezeu va veni negreșit în ajutorul vostru; atunci să luați de aici oasele mele cu voi.”", "Au pornit din Sucot și și-au așezat tabăra la Etam, la marginea pustiei.", "DOMNUL mergea înaintea lor ziua într-un stâlp de nor, ca să-i călăuzească pe drum, iar noaptea într-un stâlp de foc, ca să le dea lumină, pentru ca ei să poată merge zi și noapte.", "Stâlpul de nor nu se îndepărta dinaintea poporului ziua, nici stâlpul de foc noaptea."],
    14: ["DOMNUL i-a vorbit lui Moise și i-a spus:", "„Spune-le fiilor lui Israel să se întoarcă și să-și așeze tabăra înaintea Pi-Hahirotului, între Migdol și mare, în fața lui Baal-Țefon. Să vă așezați tabăra lângă mare, față în față cu acel loc.", "Faraonul va spune despre fiii lui Israel: «S-au rătăcit în țară; pustia i-a închis.»", "Eu voi împietri inima faraonului, iar el îi va urmări. Îmi voi arăta gloria asupra faraonului și asupra întregii lui oștiri, iar egiptenii vor ști că Eu sunt DOMNUL.” Ei au făcut astfel.", "Când regelui Egiptului i s-a spus că poporul fugise, inima faraonului și a slujitorilor lui s-a schimbat față de popor și au spus: „Ce am făcut, lăsându-l pe Israel să plece din slujba noastră?”", "Faraonul și-a pregătit carul și și-a luat poporul cu el.", "A luat șase sute de care alese și toate celelalte care ale Egiptului, fiecare cu căpeteniile lui.", "DOMNUL a împietrit inima faraonului, regele Egiptului, iar acesta i-a urmărit pe fiii lui Israel. Fiii lui Israel ieșeau cu mâna ridicată.", "Egiptenii i-au urmărit și i-au ajuns când își așezaseră tabăra lângă mare, lângă Pi-Hahirot, în fața lui Baal-Țefon: toți caii și carele faraonului, călăreții și oștirea lui.", "Când faraonul s-a apropiat, fiii lui Israel și-au ridicat ochii și iată că egiptenii veneau după ei. Atunci s-au înspăimântat foarte tare și au strigat către DOMNUL.", "I-au spus lui Moise: „Pentru că nu erau morminte în Egipt ne-ai adus să murim în pustiu? Ce ne-ai făcut, scoțându-ne din Egipt?", "Nu acesta este cuvântul pe care ți l-am spus în Egipt: «Lasă-ne în pace ca să le slujim egiptenilor»? Era mai bine pentru noi să le slujim egiptenilor decât să murim în pustiu.”", "Moise a spus poporului: „Nu vă temeți! Stați pe loc și priviți izbăvirea pe care DOMNUL o va înfăptui astăzi pentru voi, căci pe egiptenii pe care îi vedeți astăzi nu-i veți mai vedea niciodată.", "DOMNUL va lupta pentru voi, iar voi să tăceți.”", "DOMNUL i-a spus lui Moise: „De ce strigi către Mine? Spune-le fiilor lui Israel să pornească înainte.", "Ridică-ți toiagul, întinde-ți mâna peste mare și desparte-o, iar fiii lui Israel vor intra prin mijlocul mării pe uscat.", "Iată, Eu voi împietri inimile egiptenilor, iar ei vor intra după fiii lui Israel. Îmi voi arăta gloria asupra faraonului și asupra întregii lui oștiri, asupra carelor și călăreților lui.", "Egiptenii vor ști că Eu sunt DOMNUL când Îmi voi arăta gloria asupra faraonului, asupra carelor și călăreților lui.”", "Îngerul lui Dumnezeu, care mergea înaintea taberei lui Israel, s-a mutat și a mers în urma lor. Stâlpul de nor s-a mutat dinaintea lor și s-a așezat în urma lor.", "A venit între tabăra Egiptului și tabăra lui Israel. Norul aducea întuneric pentru unii și lumina noaptea pentru ceilalți, astfel încât o tabără nu s-a apropiat de cealaltă toată noaptea.", "Moise și-a întins mâna peste mare, iar DOMNUL a făcut marea să se retragă toată noaptea printr-un vânt puternic de răsărit. A prefăcut marea în uscat, iar apele s-au despărțit.", "Fiii lui Israel au intrat prin mijlocul mării pe uscat, iar apele erau ca un zid la dreapta și la stânga lor.", "Egiptenii i-au urmărit și au intrat după ei în mijlocul mării: toți caii faraonului, carele și călăreții lui.", "În straja dimineții, DOMNUL a privit spre tabăra egiptenilor din stâlpul de foc și de nor și a adus tulburare în tabăra egiptenilor.", "A făcut ca roțile carelor lor să meargă cu greu. Atunci egiptenii au spus: „Să fugim dinaintea lui Israel, căci DOMNUL luptă pentru ei împotriva Egiptului!”", "DOMNUL i-a spus lui Moise: „Întinde-ți mâna peste mare, ca apele să se întoarcă peste egipteni, peste carele și călăreții lor.”", "Moise și-a întins mâna peste mare, iar spre dimineață marea s-a întors la puterea ei. Egiptenii fugeau în întâmpinarea ei, iar DOMNUL i-a aruncat pe egipteni în mijlocul mării.", "Apele s-au întors și au acoperit carele, călăreții și întreaga oștire a faraonului care intrase după ei în mare. Nu a mai rămas niciunul dintre ei.", "Dar fiii lui Israel au mers pe uscat prin mijlocul mării, iar apele erau ca un zid la dreapta și la stânga lor.", "În ziua aceea, DOMNUL l-a izbăvit pe Israel din mâna egiptenilor, iar Israel i-a văzut pe egipteni morți pe țărmul mării.", "Israel a văzut lucrarea cea mare pe care DOMNUL o făcuse împotriva egiptenilor. Poporul s-a temut de DOMNUL și a crezut în DOMNUL și în Moise, slujitorul Său."],
    15: ["Atunci Moise și fiii lui Israel I-au cântat DOMNULUI această cântare: „Voi cânta DOMNULUI, căci S-a înălțat cu măreție; a aruncat în mare calul și călărețul lui.", "Yah este tăria și cântarea mea și a devenit izbăvirea mea. El este Dumnezeul meu și Îl voi lăuda, Dumnezeul tatălui meu și Îl voi înălța.", "DOMNUL este un războinic; DOMNUL este Numele Lui.", "A aruncat în mare carele faraonului și oștirea lui; căpeteniile lui alese s-au scufundat în Marea Roșie.", "Adâncurile i-au acoperit; s-au coborât în adâncimi ca o piatră.", "Dreapta Ta, DOMNULE, este măreață în putere; dreapta Ta, DOMNULE, îl sfărâmă pe dușman.", "În măreția slavei Tale îi dobori pe cei care se ridică împotriva Ta; Îți trimiți mânia și ea îi mistuie ca pe paie.", "La suflarea nărilor Tale, apele s-au îngrămădit; șuvoaiele au stat ca un zid, adâncurile s-au închegat în inima mării.", "Dușmanul a spus: «Îi voi urmări, îi voi ajunge, voi împărți prada; dorința mea se va sătura cu ei. Îmi voi scoate sabia, iar mâna mea îi va nimici.»", "Ai suflat cu vântul Tău și marea i-a acoperit; s-au scufundat ca plumbul în apele puternice.", "Cine este ca Tine între dumnezei, DOMNULE? Cine este ca Tine, măreț în sfințenie, înfricoșător în laude și făcător de minuni?", "Ți-ai întins dreapta, iar pământul i-a înghițit.", "Prin bunătatea Ta statornică ai călăuzit poporul pe care l-ai răscumpărat; prin puterea Ta l-ai condus spre locuința Ta sfântă.", "Popoarele au auzit și tremură; groaza i-a cuprins pe locuitorii Filistiei.", "Atunci căpeteniile Edomului s-au înspăimântat, tremurul i-a cuprins pe conducătorii Moabului, iar toți locuitorii Canaanului s-au topit de frică.", "Spaima și groaza cad peste ei; prin măreția brațului Tău rămân nemișcați ca piatra, până va trece poporul Tău, DOMNULE, până va trece poporul pe care l-ai dobândit.", "Îi vei aduce și îi vei sădi pe muntele moștenirii Tale, în locul pe care l-ai pregătit ca locuință, DOMNULE, în sanctuarul pe care mâinile Tale l-au întemeiat, Stăpâne.", "DOMNUL va domni pentru totdeauna și în vecii vecilor.”", "Când caii faraonului, carele și călăreții lui au intrat în mare, DOMNUL a adus peste ei apele mării, dar fiii lui Israel au mers pe uscat prin mijlocul mării.", "Maria, profetesa, sora lui Aaron, a luat o tamburină în mână, iar toate femeile au ieșit după ea cu tamburine și dansuri.", "Maria le răspundea: „Cântați DOMNULUI, căci S-a înălțat cu măreție; a aruncat în mare calul și călărețul lui.”", "Moise l-a făcut pe Israel să pornească de la Marea Roșie. Au ieșit în pustia Șur și au mers trei zile prin pustie fără să găsească apă.", "Când au ajuns la Mara, nu au putut bea apa de acolo, fiindcă era amară. De aceea locul a fost numit Mara.", "Poporul a murmurat împotriva lui Moise și a spus: „Ce vom bea?”", "Moise a strigat către DOMNUL, iar DOMNUL i-a arătat o bucată de lemn. El a aruncat-o în apă, iar apa a devenit dulce. Acolo DOMNUL le-a dat o poruncă și o hotărâre și acolo i-a pus la încercare.", "El a spus: „Dacă vei asculta cu atenție glasul DOMNULUI, Dumnezeul tău, vei face ce este drept în ochii Lui, vei lua aminte la poruncile Lui și vei păzi toate rânduielile Lui, nu voi pune peste tine niciuna dintre bolile pe care le-am pus peste egipteni, căci Eu sunt DOMNUL, Cel care te vindecă.”", "Apoi au ajuns la Elim, unde erau douăsprezece izvoare de apă și șaptezeci de palmieri, și și-au așezat tabăra acolo, lângă ape."],
    16: ["Au pornit din Elim, iar întreaga comunitate a fiilor lui Israel a ajuns în pustia Sin, care este între Elim și Sinai, în ziua a cincisprezecea a lunii a doua după ieșirea lor din țara Egiptului.", "Întreaga comunitate a fiilor lui Israel a murmurat în pustie împotriva lui Moise și a lui Aaron.", "Fiii lui Israel le-au spus: „Mai bine am fi murit de mâna DOMNULUI în țara Egiptului, când stăteam lângă oalele cu carne și mâncam pâine pe săturate! Ne-ați adus în pustia aceasta ca să omorâți de foame întreaga adunare.”", "Atunci DOMNUL i-a spus lui Moise: „Iată, voi face să plouă pentru voi pâine din cer. Poporul să iasă și să strângă în fiecare zi porția necesară pentru acea zi, ca să-l pun la încercare și să văd dacă va umbla sau nu după Legea Mea.", "În ziua a șasea, când vor pregăti ceea ce au adus, va fi de două ori mai mult decât strâng în fiecare zi.”", "Moise și Aaron le-au spus tuturor fiilor lui Israel: „Diseară veți ști că DOMNUL v-a scos din țara Egiptului,", "iar dimineață veți vedea gloria DOMNULUI, fiindcă El a auzit murmurele voastre împotriva DOMNULUI. Cine suntem noi, ca să murmurați împotriva noastră?”", "Moise a mai spus: „DOMNUL vă va da diseară carne de mâncat, iar dimineață pâine ca să vă săturați, fiindcă DOMNUL a auzit murmurele pe care le-ați rostit împotriva Lui. Cine suntem noi? Murmurele voastre nu sunt împotriva noastră, ci împotriva DOMNULUI.”", "Moise i-a spus lui Aaron: „Spune întregii comunități a fiilor lui Israel: «Apropiați-vă înaintea DOMNULUI, căci El a auzit murmurele voastre.»”", "În timp ce Aaron vorbea întregii comunități a fiilor lui Israel, ei s-au întors spre pustie și iată că gloria DOMNULUI s-a arătat în nor.", "DOMNUL i-a vorbit lui Moise și i-a spus:", "„Am auzit murmurele fiilor lui Israel. Vorbește-le și spune-le: «Spre seară veți mânca carne, iar dimineață vă veți sătura cu pâine. Atunci veți ști că Eu sunt DOMNUL, Dumnezeul vostru.»”", "Seara au venit prepelițe și au acoperit tabăra, iar dimineața un strat de rouă era în jurul taberei.", "Când stratul de rouă s-a ridicat, iată că pe suprafața pustiei era ceva mărunt și solzos, mărunt ca bruma pe pământ.", "Când fiii lui Israel au văzut, și-au spus unii altora: „Ce este aceasta?”, fiindcă nu știau ce era. Moise le-a spus: „Aceasta este pâinea pe care v-a dat-o DOMNUL ca hrană.", "Iată ce a poruncit DOMNUL: «Fiecare să strângă cât îi trebuie pentru hrană: câte un omer de persoană, după numărul celor din cortul său.»”", "Fiii lui Israel au făcut astfel; unii au strâns mai mult, iar alții mai puțin.", "Când au măsurat cu omerul, celui care strânsese mult nu i-a rămas în plus, iar celui care strânsese puțin nu i-a lipsit. Fiecare strânsese cât îi trebuia pentru hrană.", "Moise le-a spus: „Nimeni să nu lase din ea până dimineață.”", "Dar unii nu l-au ascultat pe Moise și au lăsat din ea până dimineață. A făcut viermi și a început să miroasă urât, iar Moise s-a mâniat pe ei.", "O strângeau în fiecare dimineață, fiecare cât îi trebuia pentru hrană. Când se încingea soarele, se topea.", "În ziua a șasea au strâns de două ori mai multă pâine, câte doi omeri de persoană. Toate căpeteniile comunității au venit și i-au spus lui Moise.", "El le-a răspuns: „Aceasta este ceea ce a spus DOMNUL: «Mâine este o odihnă deplină, un Sabat sfânt pentru DOMNUL. Coaceți ce aveți de copt și fierbeți ce aveți de fiert, iar tot ce rămâne păstrați pentru dimineață.»”", "Au păstrat-o până dimineață, așa cum poruncise Moise, și nu a început să miroasă urât și nici nu au apărut viermi în ea.", "Moise a spus: „Mâncați-o astăzi, căci astăzi este Sabat pentru DOMNUL. Astăzi nu o veți găsi pe câmp.", "Șase zile să o strângeți, dar în ziua a șaptea este Sabatul și nu va fi deloc.”", "Totuși, în ziua a șaptea, unii dintre oameni au ieșit să strângă, dar nu au găsit nimic.", "DOMNUL i-a spus lui Moise: „Până când veți refuza să păziți poruncile și legile Mele?", "Vedeți că DOMNUL v-a dat Sabatul; de aceea, în ziua a șasea vă dă pâine pentru două zile. Fiecare să rămână la locul său și nimeni să nu iasă din locul lui în ziua a șaptea.”", "Astfel, poporul s-a odihnit în ziua a șaptea.", "Casa lui Israel a numit hrana aceea „mană”. Era ca sămânța de coriandru, albă, iar gustul ei era ca al unei turte cu miere.", "Moise a spus: „Iată ce a poruncit DOMNUL: «Să se păstreze un omer plin din ea pentru generațiile voastre, ca să vadă pâinea cu care v-am hrănit în pustie când v-am scos din țara Egiptului.»”", "Moise i-a spus lui Aaron: „Ia un vas, pune în el un omer plin cu mană și așază-l înaintea DOMNULUI, ca să fie păstrat pentru generațiile voastre.”", "Așa cum îi poruncise DOMNUL lui Moise, Aaron l-a așezat înaintea Mărturiei, ca să fie păstrat.", "Fiii lui Israel au mâncat mană timp de patruzeci de ani, până când au ajuns într-o țară locuită. Au mâncat mană până când au ajuns la hotarul țării Canaanului.", "Un omer este a zecea parte dintr-o efă."],
    17: ["Întreaga comunitate a fiilor lui Israel a pornit din pustia Sin, călătorind din loc în loc după porunca DOMNULUI, și și-a așezat tabăra la Refidim. Dar nu era apă de băut pentru popor.", "Poporul s-a certat cu Moise și a spus: „Dați-ne apă să bem!” Moise le-a răspuns: „De ce vă certați cu mine? De ce Îl puneți la încercare pe DOMNUL?”", "Poporul era însetat acolo și a murmurat împotriva lui Moise: „De ce ne-ai scos din Egipt? Ca să ne omori de sete pe noi, pe copiii noștri și animalele noastre?”", "Moise a strigat către DOMNUL: „Ce să fac cu poporul acesta? Puțin mai este și mă vor ucide cu pietre!”", "DOMNUL i-a spus lui Moise: „Treci înaintea poporului și ia cu tine câțiva dintre bătrânii lui Israel. Ia în mână toiagul cu care ai lovit Nilul și mergi.", "Iată, Eu voi sta înaintea ta acolo, pe stâncă, la Horeb. Vei lovi stânca, iar din ea va ieși apă și poporul va bea.” Moise a făcut astfel înaintea bătrânilor lui Israel.", "El a numit locul Masa și Meriba, din cauza certei fiilor lui Israel și pentru că Îl puseseră la încercare pe DOMNUL, spunând: „Este DOMNUL în mijlocul nostru sau nu?”", "Atunci Amalec a venit și a luptat împotriva lui Israel la Refidim.", "Moise i-a spus lui Iosua: „Alege pentru noi bărbați și ieși să lupți împotriva lui Amalec. Mâine voi sta pe vârful dealului cu toiagul lui Dumnezeu în mână.”", "Iosua a făcut cum îi spusese Moise și a luptat împotriva lui Amalec, iar Moise, Aaron și Hur s-au urcat pe vârful dealului.", "Când Moise își ținea mâna ridicată, Israel biruia; când își lăsa mâna, Amalec biruia.", "Mâinile lui Moise au obosit. Atunci au luat o piatră, au pus-o sub el și s-a așezat pe ea. Aaron și Hur îi sprijineau mâinile, unul de o parte și celălalt de cealaltă parte, iar mâinile lui au rămas neclintite până la apusul soarelui.", "Iosua l-a învins pe Amalec și poporul lui cu tăișul sabiei.", "DOMNUL i-a spus lui Moise: „Scrie acest lucru într-o carte ca aducere-aminte și pune-l în auzul lui Iosua: voi șterge cu desăvârșire amintirea lui Amalec de sub cer.”", "Moise a construit un altar și i-a pus numele „DOMNUL este Steagul meu”.", "El a spus: „Căci o mână este pe tronul lui Yah! DOMNUL va purta război împotriva lui Amalec din generație în generație.”"],
    18: ["Ietro, preotul Madianului și socrul lui Moise, a auzit tot ce făcuse Dumnezeu pentru Moise și pentru Israel, poporul Său, și cum îl scosese DOMNUL pe Israel din Egipt.", "Ietro, socrul lui Moise, a luat-o pe Sefora, soția lui Moise, după ce acesta o trimisese înapoi,", "împreună cu cei doi fii ai ei. Unul se numea Gherșom, căci Moise spusese: „Am locuit ca străin într-o țară străină.”", "Celălalt se numea Eliezer, căci Moise spusese: „Dumnezeul tatălui meu mi-a fost ajutor și m-a izbăvit de sabia faraonului.”", "Ietro, socrul lui Moise, a venit la Moise în pustie, împreună cu fiii și soția lui Moise, acolo unde acesta își așezase tabăra, la muntele lui Dumnezeu.", "I-a transmis lui Moise: „Eu, socrul tău Ietro, vin la tine împreună cu soția ta și cu cei doi fii ai ei.”", "Moise a ieșit în întâmpinarea socrului său, s-a plecat și l-a sărutat. S-au întrebat unul pe altul de sănătate, apoi au intrat în cort.", "Moise i-a povestit socrului său tot ce făcuse DOMNUL faraonului și egiptenilor pentru Israel, toate greutățile care îi întâmpinaseră pe drum și cum îi izbăvise DOMNUL.", "Ietro s-a bucurat de tot binele pe care DOMNUL îl făcuse lui Israel, izbăvindu-l din mâna egiptenilor.", "Ietro a spus: „Binecuvântat să fie DOMNUL, Care v-a izbăvit din mâna egiptenilor și din mâna faraonului și Care a izbăvit poporul de sub puterea egiptenilor!", "Acum știu că DOMNUL este mai mare decât toți dumnezeii, tocmai în lucrul în care egiptenii s-au purtat cu trufie împotriva lor.”", "Ietro, socrul lui Moise, a adus pentru Dumnezeu o ardere-de-tot și alte jertfe. Aaron și toți bătrânii lui Israel au venit să mănânce împreună cu socrul lui Moise înaintea lui Dumnezeu.", "A doua zi, Moise s-a așezat să judece poporul, iar oamenii au stat în jurul lui de dimineața până seara.", "Când socrul lui Moise a văzut tot ce făcea acesta pentru popor, a spus: „Ce faci tu pentru popor? De ce stai singur, iar tot poporul stă în jurul tău de dimineața până seara?”", "Moise i-a răspuns socrului său: „Pentru că poporul vine la mine să-L întrebe pe Dumnezeu.", "Când au o neînțelegere, vin la mine; eu judec între un om și semenul său și le fac cunoscute hotărârile și legile lui Dumnezeu.”", "Socrul lui Moise i-a spus: „Ceea ce faci nu este bine.", "Te vei epuiza cu siguranță, atât tu, cât și poporul acesta care este cu tine, căci sarcina este prea grea pentru tine. Nu o poți îndeplini singur.", "Ascultă acum glasul meu. Îți voi da un sfat, iar Dumnezeu să fie cu tine. Tu să reprezinți poporul înaintea lui Dumnezeu și să aduci neînțelegerile lor înaintea lui Dumnezeu.", "Să-i înveți hotărârile și legile, să le arăți calea pe care trebuie să umble și lucrarea pe care trebuie să o facă.", "Alege din tot poporul bărbați capabili, care se tem de Dumnezeu, oameni de încredere, care urăsc câștigul nedrept. Pune-i peste oameni drept căpetenii peste mii, peste sute, peste cincizeci și peste zeci.", "Ei să judece poporul în orice vreme. Orice problemă grea să o aducă la tine, iar problemele mici să le judece ei. Astfel îți va fi mai ușor, iar ei vor purta povara împreună cu tine.", "Dacă vei face lucrul acesta și dacă Dumnezeu îți poruncește astfel, vei putea rezista, iar tot poporul acesta va ajunge în pace la locul său.”", "Moise a ascultat glasul socrului său și a făcut tot ce spusese el.", "Moise a ales bărbați capabili din tot Israelul și i-a pus conducători peste popor: căpetenii peste mii, peste sute, peste cincizeci și peste zeci.", "Ei judecau poporul în orice vreme. Problemele grele le aduceau la Moise, iar problemele mici le judecau ei înșiși.", "Apoi Moise i-a dat drumul socrului său, iar acesta a plecat în țara lui."],
    19: ["În luna a treia după ieșirea fiilor lui Israel din țara Egiptului, chiar în ziua aceea, au ajuns în pustia Sinai.", "Au pornit din Refidim, au ajuns în pustia Sinai și și-au așezat tabăra în pustie. Israel și-a așezat tabăra acolo, înaintea muntelui.", "Moise s-a urcat la Dumnezeu, iar DOMNUL l-a chemat de pe munte și i-a spus: „Așa să vorbești casei lui Iacov și să le spui fiilor lui Israel:", "«Ați văzut ce le-am făcut egiptenilor și cum v-am purtat pe aripi de vultur și v-am adus la Mine.", "Acum, dacă veți asculta cu adevărat glasul Meu și veți păzi legământul Meu, veți fi comoara Mea deosebită dintre toate popoarele, căci al Meu este tot pământul.", "Îmi veți fi o împărăție de preoți și un popor sfânt.» Acestea sunt cuvintele pe care să le spui fiilor lui Israel.”", "Moise a venit, i-a chemat pe bătrânii poporului și a pus înaintea lor toate aceste cuvinte pe care i le poruncise DOMNUL.", "Tot poporul a răspuns într-un glas: „Vom face tot ce a spus DOMNUL.” Moise a dus cuvintele poporului înapoi la DOMNUL.", "DOMNUL i-a spus lui Moise: „Iată, voi veni la tine într-un nor gros, ca poporul să audă când vorbesc cu tine și să aibă întotdeauna încredere în tine.” Moise I-a spus DOMNULUI cuvintele poporului.", "DOMNUL i-a spus lui Moise: „Du-te la popor și sfințește-l astăzi și mâine. Să-și spele hainele", "și să fie gata pentru ziua a treia, căci în ziua a treia DOMNUL va coborî înaintea ochilor întregului popor pe muntele Sinai.", "Să pui hotare de jur împrejurul poporului și să spui: «Aveți grijă să nu vă urcați pe munte și să nu-i atingeți marginea. Oricine va atinge muntele va fi omorât.", "Nicio mână să nu-l atingă, ci să fie ucis cu pietre sau străpuns cu săgeți. Fie animal, fie om, nu va trăi.» Când cornul va suna prelung, ei se vor putea apropia de munte.”", "Moise a coborât de pe munte la popor, a sfințit poporul, iar ei și-au spălat hainele.", "El a spus poporului: „Fiți gata pentru ziua a treia. Să nu vă apropiați de femei.”", "În dimineața zilei a treia au fost tunete, fulgere și un nor gros pe munte și s-a auzit un sunet de corn foarte puternic. Tot poporul din tabără a tremurat.", "Moise a scos poporul din tabără în întâmpinarea lui Dumnezeu, iar ei s-au așezat la poalele muntelui.", "Tot muntele Sinai fumega, fiindcă DOMNUL coborâse peste el în foc. Fumul lui se ridica asemenea fumului unui cuptor, iar întregul munte se cutremura puternic.", "Sunetul cornului devenea tot mai puternic. Moise vorbea, iar Dumnezeu îi răspundea prin glas.", "DOMNUL a coborât pe muntele Sinai, pe vârful muntelui. DOMNUL l-a chemat pe Moise pe vârful muntelui, iar Moise s-a urcat.", "DOMNUL i-a spus lui Moise: „Coboară și avertizează poporul să nu dea năvală spre DOMNUL ca să privească, altfel mulți dintre ei vor pieri.", "Chiar și preoții care se apropie de DOMNUL să se sfințească, pentru ca DOMNUL să nu izbucnească împotriva lor.”", "Moise I-a spus DOMNULUI: „Poporul nu se poate urca pe muntele Sinai, căci Tu ne-ai avertizat: «Pune hotare în jurul muntelui și sfințește-l.»”", "DOMNUL i-a răspuns: „Coboară! Apoi să urci împreună cu Aaron. Dar preoții și poporul să nu dea năvală să urce spre DOMNUL, ca El să nu izbucnească împotriva lor.”", "Moise a coborât la popor și le-a spus aceste lucruri."],
    20: ["Dumnezeu a rostit toate aceste cuvinte:", "„Eu sunt DOMNUL, Dumnezeul tău, Care te-am scos din țara Egiptului, din casa robiei.", "Să nu ai alți dumnezei înaintea Mea.", "Să nu-ți faci idol și nicio imagine a ceea ce este în ceruri sus, pe pământ jos sau în apele de sub pământ.", "Să nu te pleci înaintea lor și să nu le slujești, căci Eu, DOMNUL, Dumnezeul tău, sunt un Dumnezeu gelos, Care cercetez vina părinților în copii până la a treia și a patra generație a celor care Mă urăsc,", "dar arăt bunătate statornică până la mii de generații celor care Mă iubesc și păzesc poruncile Mele.", "Să nu folosești Numele DOMNULUI, Dumnezeul tău, pentru ceva fals sau lipsit de valoare, căci DOMNUL nu-l va socoti nevinovat pe cel care Îi folosește Numele astfel.", "Adu-ți aminte de ziua Sabatului ca să o sfințești.", "Șase zile să lucrezi și să-ți faci toată munca,", "dar ziua a șaptea este un Sabat pentru DOMNUL, Dumnezeul tău. Să nu faci nicio muncă: nici tu, nici fiul tău, nici fiica ta, nici sclavul tău, nici sclava ta, nici animalele tale, nici străinul care este în cetățile tale.", "Căci în șase zile DOMNUL a făcut cerurile, pământul, marea și tot ce este în ele, iar în ziua a șaptea S-a odihnit. De aceea DOMNUL a binecuvântat ziua Sabatului și a sfințit-o.", "Cinstește-l pe tatăl tău și pe mama ta, pentru ca zilele tale să fie îndelungate în țara pe care ți-o dă DOMNUL, Dumnezeul tău.", "Să nu comiți omor.", "Să nu comiți adulter.", "Să nu furi.", "Să nu depui mărturie falsă împotriva semenului tău.", "Să nu poftești casa semenului tău. Să nu poftești soția semenului tău, nici sclavul lui, nici sclava lui, nici boul lui, nici măgarul lui și nimic din ce este al semenului tău.”", "Tot poporul percepea tunetele, fulgerele, sunetul cornului și muntele fumegând. Când poporul a văzut acestea, a tremurat și a rămas la distanță.", "Ei i-au spus lui Moise: „Vorbește-ne tu și vom asculta, dar să nu ne vorbească Dumnezeu, ca să nu murim.”", "Moise a spus poporului: „Nu vă temeți, căci Dumnezeu a venit ca să vă pună la încercare și pentru ca teama de El să fie înaintea voastră, ca să nu păcătuiți.”", "Poporul a rămas la distanță, iar Moise s-a apropiat de întunericul gros în care era Dumnezeu.", "DOMNUL i-a spus lui Moise: „Așa să le vorbești fiilor lui Israel: «Voi înșivă ați văzut că v-am vorbit din cer.", "Să nu vă faceți dumnezei de argint alături de Mine și să nu vă faceți dumnezei de aur.", "Să-Mi faci un altar de pământ și să aduci pe el arderile-de-tot și jertfele de pace, oile și vitele tale. În orice loc în care voi face ca Numele Meu să fie amintit, voi veni la tine și te voi binecuvânta.", "Dacă Îmi vei face un altar de piatră, să nu-l construiești din pietre cioplite, căci, dacă îți vei ridica unealta asupra lor, le vei profana.", "Să nu urci pe trepte la altarul Meu, ca să nu ți se descopere goliciunea înaintea lui.»”"],
    21: ["„Acestea sunt hotărârile pe care să le pui înaintea lor:", "Dacă vei cumpăra un sclav evreu, el să slujească șase ani, iar în al șaptelea să plece liber, fără să plătească nimic.", "Dacă a intrat singur, să plece singur. Dacă era căsătorit, soția lui să plece împreună cu el.", "Dacă stăpânul lui i-a dat o soție, iar ea i-a născut fii sau fiice, soția și copiii ei vor rămâne ai stăpânului, iar el va pleca singur.", "Dar dacă sclavul va spune hotărât: «Îmi iubesc stăpânul, soția și copiii; nu vreau să plec liber»,", "stăpânul lui să-l aducă înaintea lui Dumnezeu, apoi să-l ducă la ușă sau la ușorul ușii. Stăpânul lui să-i străpungă urechea cu o sulă, iar el îi va sluji pe termen nelimitat.", "Dacă un bărbat își vinde fiica drept sclavă, ea să nu plece așa cum pleacă sclavii de parte bărbătească.", "Dacă nu-i mai place stăpânului ei, care o destinase pentru sine, acesta să-i permită răscumpărarea. Nu are dreptul să o vândă unui popor străin, fiindcă s-a purtat cu necredincioșie față de ea.", "Dacă o destinează fiului său, să se poarte cu ea potrivit drepturilor unei fiice.", "Dacă își ia o altă soție, să nu-i reducă celei dintâi hrana, îmbrăcămintea și drepturile conjugale.", "Dacă nu-i asigură aceste trei lucruri, ea va putea pleca liberă, fără să plătească argint.", "Cine lovește un om și îi provoacă moartea să fie omorât.", "Dar dacă nu a acționat cu intenție, ci Dumnezeu a îngăduit să se întâmple, îți voi stabili un loc unde să poată fugi.", "Dacă un om acționează cu premeditare împotriva semenului său și îl omoară prin viclenie, să-l iei chiar și de la altarul Meu ca să moară.", "Cine își lovește tatăl sau mama să fie omorât.", "Cine răpește o persoană, fie că a vândut-o, fie că persoana este găsită în posesia lui, să fie omorât.", "Cine își blestemă tatăl sau mama să fie omorât.", "Dacă doi bărbați se ceartă și unul îl lovește pe celălalt cu o piatră sau cu pumnul, iar acesta nu moare, ci rămâne la pat,", "dacă se ridică și umblă afară sprijinindu-se în toiag, cel care l-a lovit nu va fi condamnat pentru omor. Totuși, să-i plătească timpul pierdut și să se îngrijească de vindecarea lui deplină.", "Dacă un om își lovește sclavul sau sclava cu toiagul și acesta moare sub mâna lui, stăpânul să fie pedepsit.", "Dar dacă sclavul supraviețuiește o zi sau două, stăpânul nu va fi pedepsit ca pentru omor, fiindcă sclavul reprezintă argintul lui.", "Dacă niște bărbați se bat și lovesc o femeie însărcinată, iar copilul ei se naște înainte de vreme, dar nu urmează o vătămare gravă, vinovatul să plătească despăgubirea cerută de soțul femeii și stabilită de judecători.", "Dar dacă urmează o vătămare gravă, să dai viață pentru viață,", "ochi pentru ochi, dinte pentru dinte, mână pentru mână, picior pentru picior,", "arsură pentru arsură, rană pentru rană și vânătaie pentru vânătaie.", "Dacă un om lovește ochiul sclavului sau al sclavei sale și îl distruge, să-l lase liber ca despăgubire pentru ochi.", "Dacă îi scoate un dinte sclavului sau sclavei sale, să-l lase liber ca despăgubire pentru dinte.", "Dacă un bou împunge un bărbat sau o femeie și îi provoacă moartea, boul să fie ucis cu pietre, iar carnea lui să nu fie mâncată. Proprietarul boului nu va fi răspunzător.", "Dar dacă boul obișnuia să împungă și proprietarul fusese avertizat, însă nu l-a ținut închis, iar boul a omorât un bărbat sau o femeie, boul să fie ucis cu pietre, iar proprietarul lui să fie și el condamnat la moarte.", "Dacă i se impune un preț de răscumpărare, să dea pentru răscumpărarea vieții sale tot ce i se va impune.", "Dacă boul a împuns un fiu sau o fiică, să i se aplice proprietarului aceeași hotărâre.", "Dacă boul împunge un sclav sau o sclavă, proprietarul să dea stăpânului acestuia treizeci de șecheli de argint, iar boul să fie ucis cu pietre.", "Dacă un om lasă deschisă o groapă sau sapă o groapă și nu o acoperă, iar un bou sau un măgar cade în ea,", "proprietarul gropii să plătească despăgubirea proprietarului animalului, iar animalul mort va fi al lui.", "Dacă boul unui om rănește boul altuia și acesta moare, să vândă boul viu și să împartă prețul lui; să împartă și animalul mort.", "Dar dacă se știa că boul obișnuia să împungă, iar proprietarul nu l-a ținut închis, acesta să dea bou pentru bou, iar animalul mort va fi al lui.”"],
    22: ["„Dacă un om fură un bou sau o oaie și o înjunghie ori o vinde, să dea cinci boi pentru un bou și patru oi pentru o oaie.", "Dacă hoțul este prins în timp ce sparge o casă și este lovit mortal, cel care l-a lovit nu va avea vină de sânge.", "Dar dacă soarele răsărise deja, cel care l-a omorât va avea vină de sânge. Hoțul să plătească despăgubirea; dacă nu are cu ce, să fie vândut pentru furtul său.", "Dacă animalul furat este găsit viu în posesia sa, fie bou, măgar sau oaie, să plătească dublu.", "Dacă un om își lasă animalul să pască într-un ogor sau într-o vie și acesta paște în ogorul altuia, să despăgubească din ce are mai bun în propriul ogor și în propria vie.", "Dacă izbucnește un foc, cuprinde mărăcinii și arde snopii, grâul încă în picioare sau ogorul, cel care a aprins focul să plătească întreaga despăgubire.", "Dacă un om îi încredințează semenului său argint sau bunuri ca să le păstreze, iar acestea sunt furate din casa lui, hoțul, dacă este găsit, să plătească dublu.", "Dacă hoțul nu este găsit, stăpânul casei să se apropie înaintea lui Dumnezeu ca să se stabilească dacă și-a însușit bunurile semenului său.", "În orice caz de însușire necinstită, cu privire la bou, măgar, oaie, haină sau orice obiect pierdut despre care cineva spune: «Acesta este al meu», cauza ambelor părți să ajungă înaintea lui Dumnezeu. Cel pe care Dumnezeu îl va declara vinovat să-i plătească semenului său dublu.", "Dacă un om îi încredințează semenului său un măgar, un bou, o oaie sau orice alt animal ca să-l păstreze, iar animalul moare, este rănit sau este luat fără să vadă cineva,", "între cei doi să fie un jurământ înaintea DOMNULUI că păzitorul nu și-a însușit bunul semenului său. Proprietarul să accepte jurământul, iar păzitorul nu va plăti despăgubire.", "Dar dacă animalul i-a fost furat, păzitorul să-l despăgubească pe proprietar.", "Dacă animalul a fost sfâșiat de fiare, să aducă rămășițele ca dovadă și nu va plăti pentru animalul sfâșiat.", "Dacă un om împrumută un animal de la semenul său, iar acesta este rănit sau moare când proprietarul nu era de față, să plătească întreaga despăgubire.", "Dacă proprietarul era de față, să nu plătească. Dacă animalul era închiriat, despăgubirea este inclusă în plata chiriei.", "Dacă un bărbat seduce o fecioară care nu este logodită și se culcă cu ea, să plătească prețul de căsătorie și să o ia de soție.", "Dacă tatăl ei refuză categoric să i-o dea, bărbatul să plătească o sumă egală cu prețul de căsătorie al fecioarelor.", "Să nu lași în viață o femeie care practică vrăjitoria.", "Oricine întreține relații sexuale cu un animal să fie omorât.", "Cine aduce jertfe unui dumnezeu, în afară de DOMNUL singur, să fie dat spre nimicire.", "Să nu nedreptățești și să nu asuprești străinul, căci și voi ați fost străini în țara Egiptului.", "Să nu exploatezi nicio văduvă și niciun copil rămas fără tată.", "Dacă îi exploatezi și ei strigă către Mine, le voi auzi negreșit strigătul.", "Mânia Mea se va aprinde și vă voi omorî cu sabia; soțiile voastre vor ajunge văduve, iar copiii voștri vor rămâne fără tată.", "Dacă împrumuți argint unui sărac din poporul Meu care este lângă tine, să nu te porți cu el ca un creditor și să nu-i impui dobândă.", "Dacă iei drept garanție haina semenului tău, să i-o înapoiezi înainte de apusul soarelui,", "căci aceasta este singura lui învelitoare, haina pentru trupul său. În ce va dormi? Când va striga către Mine, îl voi auzi, căci Eu sunt plin de har.", "Să nu-L blasfemiezi pe Dumnezeu și să nu blestemi un conducător al poporului tău.", "Să nu întârzii să aduci din plinătatea recoltei tale și din ceea ce curge din teascurile tale. Să-Mi dai pe întâiul născut dintre fiii tăi.", "Să faci la fel cu vitele și cu oile tale. Întâiul născut să rămână șapte zile cu mama sa, iar în ziua a opta să Mi-l dai.", "Să-Mi fiți oameni sfinți. Să nu mâncați carne sfâșiată de fiare pe câmp, ci să o aruncați câinilor.”"],
    23: ["„Să nu răspândești un zvon fals. Să nu-ți unești mâna cu cel rău ca să fii martor răuvoitor.", "Să nu urmezi mulțimea ca să faci rău și să nu depui mărturie într-un proces înclinând după majoritate ca să pervertești dreptatea.", "Să nu-l favorizezi nici pe sărac în procesul lui.", "Dacă întâlnești boul sau măgarul dușmanului tău rătăcind, să i-l aduci înapoi.", "Dacă vezi măgarul celui care te urăște căzut sub povara lui, să nu-l lași acolo, ci să-l ajuți să-l elibereze.", "Să nu denaturezi dreptatea săracului tău în procesul lui.", "Să te ții departe de o acuzație falsă. Să nu-l condamni la moarte pe cel nevinovat și drept, căci Eu nu-l voi declara drept pe cel vinovat.", "Să nu primești mită, căci mita îi orbește pe cei care văd limpede și răstoarnă cuvintele celor drepți.", "Să nu asuprești străinul. Voi cunoașteți sufletul străinului, căci ați fost străini în țara Egiptului.", "Șase ani să-ți semeni pământul și să-i strângi recolta,", "dar în anul al șaptelea să-l lași să se odihnească și să rămână nelucrat. Săracii poporului tău să mănânce din el, iar ce rămâne să mănânce animalele câmpului. La fel să faci cu via și cu livada ta de măslini.", "Șase zile să-ți faci lucrarea, iar în ziua a șaptea să te odihnești, pentru ca boul și măgarul tău să se odihnească, iar fiul sclavei tale și străinul să se învioreze.", "Să fiți atenți la tot ce v-am spus. Să nu chemați numele altor dumnezei și să nu se audă din gura voastră.", "De trei ori pe an să-Mi ții o sărbătoare.", "Să păzești Sărbătoarea Azimelor. Timp de șapte zile să mănânci azime, așa cum ți-am poruncit, la timpul hotărât în luna Abib, căci atunci ai ieșit din Egipt. Nimeni să nu se înfățișeze înaintea Mea cu mâna goală.", "Să păzești Sărbătoarea Secerișului, cu primele roade ale muncii tale, din ceea ce ai semănat pe câmp, și Sărbătoarea Strângerii Roadelor, la sfârșitul anului, când îți strângi rodul muncii de pe câmp.", "De trei ori pe an, toți bărbații tăi să se înfățișeze înaintea Stăpânului, DOMNUL.", "Să nu aduci sângele jertfei Mele împreună cu pâine dospită, iar grăsimea sărbătorii Mele să nu rămână peste noapte până dimineața.", "Să aduci cele dintâi dintre primele roade ale pământului tău în Casa DOMNULUI, Dumnezeul tău. Să nu fierbi un ied în laptele mamei sale.", "Iată, trimit un Înger înaintea ta, ca să te păzească pe drum și să te ducă în locul pe care l-am pregătit.", "Fii atent înaintea lui și ascultă-i glasul. Să nu te răzvrătești împotriva lui, căci nu vă va ierta răzvrătirea, fiindcă Numele Meu este în el.", "Dar dacă îi vei asculta cu adevărat glasul și vei face tot ce spun Eu, voi fi dușmanul dușmanilor tăi și potrivnicul potrivnicilor tăi.", "Îngerul Meu va merge înaintea ta și te va duce la amoriți, hetiți, periziți, canaaniți, heviți și iebusiți, iar Eu îi voi nimici.", "Să nu te pleci înaintea dumnezeilor lor, să nu le slujești și să nu urmezi practicile lor, ci să-i dărâmi cu desăvârșire și să le sfărâmi stâlpii sacri.", "Să-I slujiți DOMNULUI, Dumnezeul vostru, iar El îți va binecuvânta pâinea și apa. Voi îndepărta boala din mijlocul tău.", "În țara ta nu va fi femeie care să piardă sarcina sau să fie stearpă. Voi împlini numărul zilelor tale.", "Voi trimite groaza Mea înaintea ta și voi arunca în confuzie orice popor la care vei ajunge; îi voi face pe toți dușmanii tăi să-ți întoarcă spatele.", "Voi trimite viespea înaintea ta, iar ea îi va izgoni dinaintea ta pe heviți, canaaniți și hetiți.", "Nu-i voi izgoni dinaintea ta într-un singur an, pentru ca țara să nu ajungă pustie și animalele sălbatice să nu se înmulțească împotriva ta.", "Îi voi izgoni puțin câte puțin dinaintea ta, până când te vei înmulți și vei lua țara în stăpânire.", "Îți voi stabili hotarul de la Marea Roșie până la marea filistenilor și de la pustie până la Râu. Îi voi da pe locuitorii țării în mâna voastră, iar tu îi vei izgoni dinaintea ta.", "Să nu închei legământ cu ei și nici cu dumnezeii lor.", "Ei să nu locuiască în țara ta, ca să nu te facă să păcătuiești împotriva Mea, căci slujirea dumnezeilor lor va deveni pentru tine o cursă.”"],
    24: ["Apoi Dumnezeu i-a spus lui Moise: „Urcați la DOMNUL, tu, Aaron, Nadab, Abihu și șaptezeci dintre bătrânii lui Israel, și închinați-vă de la distanță.", "Numai Moise să se apropie de DOMNUL. Ceilalți să nu se apropie, iar poporul să nu urce împreună cu el.”", "Moise a venit și a spus poporului toate cuvintele DOMNULUI și toate hotărârile. Tot poporul a răspuns într-un glas: „Vom împlini toate cuvintele pe care le-a spus DOMNUL.”", "Moise a scris toate cuvintele DOMNULUI. S-a sculat dis-de-dimineață, a construit un altar la poalele muntelui și a ridicat doisprezece stâlpi pentru cele douăsprezece seminții ale lui Israel.", "A trimis câțiva tineri dintre fiii lui Israel, iar ei au adus arderi-de-tot și au jertfit tauri ca jertfe de pace pentru DOMNUL.", "Moise a luat jumătate din sânge și l-a pus în vase, iar cealaltă jumătate a stropit-o pe altar.", "A luat Cartea Legământului și a citit-o în auzul poporului. Ei au spus: „Vom face tot ce a spus DOMNUL și vom asculta.”", "Moise a luat sângele, a stropit poporul și a spus: „Iată sângele legământului pe care DOMNUL l-a încheiat cu voi pe temeiul tuturor acestor cuvinte.”", "Moise, Aaron, Nadab, Abihu și șaptezeci dintre bătrânii lui Israel s-au urcat.", "Ei L-au văzut pe Dumnezeul lui Israel. Sub picioarele Lui era ceva asemenea unei pardoseli din safir, limpede ca cerul însuși.", "Dumnezeu nu Și-a întins mâna împotriva conducătorilor fiilor lui Israel. Ei L-au văzut pe Dumnezeu și au mâncat și au băut.", "DOMNUL i-a spus lui Moise: „Urcă la Mine pe munte și rămâi acolo. Îți voi da tablele de piatră, Legea și porunca pe care le-am scris ca să-i înveți.”", "Moise s-a ridicat împreună cu Iosua, slujitorul său, iar Moise s-a urcat pe muntele lui Dumnezeu.", "El le-a spus bătrânilor: „Așteptați-ne aici până când ne vom întoarce la voi. Iată, Aaron și Hur sunt cu voi. Cine are o neînțelegere să meargă la ei.”", "Moise s-a urcat pe munte, iar norul a acoperit muntele.", "Gloria DOMNULUI s-a așezat pe muntele Sinai, iar norul l-a acoperit timp de șase zile. În ziua a șaptea, DOMNUL l-a chemat pe Moise din mijlocul norului.", "Înfățișarea gloriei DOMNULUI era ca un foc mistuitor pe vârful muntelui, înaintea ochilor fiilor lui Israel.", "Moise a intrat în mijlocul norului și s-a urcat pe munte. Moise a rămas pe munte patruzeci de zile și patruzeci de nopți."],
    25: ["DOMNUL i-a vorbit lui Moise și i-a spus:", "„Vorbește-le fiilor lui Israel să ia pentru Mine o contribuție. Să primiți contribuția Mea de la orice om a cărui inimă îl îndeamnă să dea.", "Aceasta este contribuția pe care să o primiți de la ei: aur, argint, bronz,", "fir albastru, purpuriu și stacojiu, in fin, păr de capră,", "piei de berbec vopsite în roșu, piei fine și lemn de salcâm,", "ulei pentru lumină, mirodenii pentru untdelemnul ungerii și pentru tămâia parfumată,", "pietre de onix și pietre de montat pentru efod și pentru pieptar.", "Să-Mi facă un sanctuar, iar Eu voi locui în mijlocul lor.", "Să faceți totul după modelul Cortului și după modelul tuturor obiectelor lui, pe care ți-l arăt.", "Să facă un chivot din lemn de salcâm, lung de doi coți și jumătate, lat de un cot și jumătate și înalt de un cot și jumătate.", "Să-l acoperi cu aur curat pe dinăuntru și pe dinafară și să-i faci de jur împrejur un chenar de aur.", "Să torni pentru el patru verigi de aur și să le fixezi la cele patru picioare: două verigi pe o latură și două pe cealaltă latură.", "Să faci drugi din lemn de salcâm și să-i acoperi cu aur.", "Să introduci drugii în verigile de pe laturile chivotului, ca să poată fi purtat cu ei.", "Drugii să rămână în verigile chivotului și să nu fie scoși din ele.", "Să pui în chivot Mărturia pe care ți-o voi da.", "Să faci un capac al ispășirii din aur curat, lung de doi coți și jumătate și lat de un cot și jumătate.", "Să faci doi heruvimi din aur bătut, la cele două capete ale capacului ispășirii.", "Să faci un heruvim la un capăt și un heruvim la celălalt capăt; să-i faceți dintr-o singură bucată cu capacul, la cele două capete ale lui.", "Heruvimii să-și întindă aripile în sus, acoperind cu aripile lor capacul ispășirii. Fețele lor să fie îndreptate una spre alta și spre capacul ispășirii.", "Să pui capacul ispășirii deasupra chivotului, iar în chivot să pui Mărturia pe care ți-o voi da.", "Acolo Mă voi întâlni cu tine și îți voi vorbi de deasupra capacului ispășirii, dintre cei doi heruvimi care sunt deasupra chivotului Mărturiei, despre tot ce îți voi porunci pentru fiii lui Israel.", "Să faci o masă din lemn de salcâm, lungă de doi coți, lată de un cot și înaltă de un cot și jumătate.", "Să o acoperi cu aur curat și să-i faci de jur împrejur un chenar de aur.", "Să-i faci de jur împrejur o margine lată de o palmă și un chenar de aur în jurul marginii.", "Să-i faci patru verigi de aur și să pui verigile în cele patru colțuri, la cele patru picioare ale mesei.", "Verigile să fie aproape de margine, ca să țină drugii cu care va fi purtată masa.", "Să faci drugii din lemn de salcâm, să-i acoperi cu aur, iar masa să fie purtată cu ei.", "Să-i faci farfuriile, lingurile, cănile și bolurile folosite la turnarea darurilor de băutură. Să le faci din aur curat.", "Să pui permanent pe masă, înaintea Mea, pâinea Prezenței.", "Să faci un sfeșnic din aur curat. Sfeșnicul să fie lucrat prin batere; baza, tija, cupele, bobocii și florile lui să fie dintr-o singură bucată cu el.", "Șase brațe să iasă din laturile lui: trei brațe ale sfeșnicului dintr-o latură și trei din cealaltă latură.", "Pe primul braț să fie trei cupe în formă de floare de migdal, fiecare cu boboc și floare, și trei cupe în formă de floare de migdal pe brațul următor, fiecare cu boboc și floare; la fel pentru cele șase brațe care ies din sfeșnic.", "Pe tija sfeșnicului să fie patru cupe în formă de floare de migdal, cu bobocii și florile lor.", "Să fie un boboc sub prima pereche de brațe, un boboc sub a doua pereche și un boboc sub a treia pereche, pentru cele șase brațe care ies din sfeșnic.", "Bobocii și brațele să fie dintr-o singură bucată cu el; întregul să fie o singură lucrare din aur curat, bătut.", "Să-i faci șapte candele și să-i așezi candelele astfel încât să lumineze spațiul dinaintea lui.", "Cleștii pentru fitil și tăvițele lui să fie din aur curat.", "Sfeșnicul și toate aceste obiecte să fie făcute dintr-un talant de aur curat.", "Vezi să le faci după modelul care ți-a fost arătat pe munte.”"],
    26: ["„Să faci Cortul din zece pânze de in fin răsucit și din fir albastru, purpuriu și stacojiu, cu heruvimi lucrați artistic.", "Fiecare pânză să fie lungă de douăzeci și opt de coți și lată de patru coți; toate pânzele să aibă aceeași măsură.", "Cinci pânze să fie prinse una de alta, iar celelalte cinci pânze să fie prinse una de alta.", "Să faci cheotori din fir albastru pe marginea pânzei de la capătul primei îmbinări și la fel pe marginea pânzei de la capătul celei de-a doua îmbinări.", "Să faci cincizeci de cheotori pe prima pânză și cincizeci de cheotori pe marginea pânzei din a doua îmbinare. Cheotorile să fie așezate față în față.", "Să faci cincizeci de copci de aur și să unești pânzele una cu alta prin copci, astfel încât Cortul să formeze un singur întreg.", "Să faci unsprezece pânze din păr de capră, ca acoperământ peste Cort.", "Fiecare pânză să fie lungă de treizeci de coți și lată de patru coți; toate cele unsprezece pânze să aibă aceeași măsură.", "Să unești separat cinci pânze și separat șase pânze, iar a șasea pânză să o îndoi în două în partea din față a cortului.", "Să faci cincizeci de cheotori pe marginea pânzei de la capătul primei îmbinări și cincizeci de cheotori pe marginea pânzei de la capătul celei de-a doua îmbinări.", "Să faci cincizeci de copci din bronz, să introduci copcile în cheotori și să unești acoperământul, ca să formeze un singur întreg.", "Partea care rămâne în plus din pânzele acoperământului, jumătatea de pânză rămasă, să atârne în partea din spate a Cortului.", "Cotul rămas pe o latură și cotul rămas pe cealaltă latură din lungimea pânzelor să atârne peste laturile Cortului, ca să-l acopere.", "Să faci pentru cort un înveliș din piei de berbec vopsite în roșu, iar deasupra lui un înveliș din piei fine.", "Să faci scândurile Cortului din lemn de salcâm și să le așezi în picioare.", "Fiecare scândură să fie lungă de zece coți și lată de un cot și jumătate.", "Fiecare scândură să aibă două cepuri paralele. Așa să faci toate scândurile Cortului.", "Să faci douăzeci de scânduri pentru latura de sud a Cortului.", "Sub cele douăzeci de scânduri să faci patruzeci de socluri de argint: două socluri sub o scândură, pentru cele două cepuri ale ei, și două socluri sub fiecare dintre celelalte scânduri.", "Pentru a doua latură a Cortului, cea de nord, să faci douăzeci de scânduri", "și patruzeci de socluri de argint: două socluri sub fiecare scândură.", "Pentru partea din spate a Cortului, spre apus, să faci șase scânduri.", "Să faci încă două scânduri pentru colțurile din spate ale Cortului.", "Ele să fie duble în partea de jos și unite până sus, la primul inel. Așa să fie amândouă, pentru cele două colțuri.", "Să fie opt scânduri cu șaisprezece socluri de argint, câte două socluri sub fiecare scândură.", "Să faci drugi din lemn de salcâm: cinci pentru scândurile de pe o latură a Cortului,", "cinci pentru scândurile de pe cealaltă latură și cinci pentru scândurile din partea din spate, spre apus.", "Drugul din mijloc să treacă prin mijlocul scândurilor de la un capăt la celălalt.", "Să acoperi scândurile cu aur, să le faci inele de aur prin care să treacă drugii și să acoperi drugii cu aur.", "Să ridici Cortul după modelul care ți-a fost arătat pe munte.", "Să faci o perdea din fir albastru, purpuriu și stacojiu și din in fin răsucit, cu heruvimi lucrați artistic.", "Să o atârni pe patru stâlpi din lemn de salcâm acoperiți cu aur, cu cârlige de aur, așezați pe patru socluri de argint.", "Să atârni perdeaua sub copci și să aduci chivotul Mărturiei dincolo de perdea. Perdeaua să despartă pentru voi Locul Sfânt de Locul Preasfânt.", "Să pui capacul ispășirii pe chivotul Mărturiei, în Locul Preasfânt.", "Să așezi masa dincoace de perdea, iar sfeșnicul în fața mesei, pe latura de sud a Cortului. Masa să o pui pe latura de nord.", "Pentru intrarea cortului să faci un paravan din fir albastru, purpuriu și stacojiu și din in fin răsucit, lucrat prin broderie.", "Pentru paravan să faci cinci stâlpi din lemn de salcâm și să-i acoperi cu aur. Cârligele lor să fie din aur, iar pentru ei să torni cinci socluri din bronz.”"],
    27: ["„Să faci altarul din lemn de salcâm, lung de cinci coți și lat de cinci coți. Altarul să fie pătrat și înalt de trei coți.", "Să-i faci coarne la cele patru colțuri; coarnele să fie dintr-o singură bucată cu el. Să-l acoperi cu bronz.", "Să-i faci vase pentru cenușă, lopeți, lighene, furculițe și fărașe pentru cărbuni. Toate uneltele lui să le faci din bronz.", "Să-i faci un grătar ca o rețea din bronz și să pui patru verigi de bronz la cele patru colțuri ale rețelei.", "Să pui rețeaua sub marginea altarului, în partea de jos, astfel încât să ajungă până la jumătatea altarului.", "Să faci drugi pentru altar, drugi din lemn de salcâm, și să-i acoperi cu bronz.", "Drugii să fie introduși în verigi și să fie pe cele două laturi ale altarului când este purtat.", "Să faci altarul gol pe dinăuntru, din scânduri. Să-l facă după cum ți-a fost arătat pe munte.", "Să faci curtea Cortului. Pe latura de sud, curtea să aibă pânze din in fin răsucit, lungi de o sută de coți.", "Să aibă douăzeci de stâlpi și douăzeci de socluri din bronz; cârligele și legăturile stâlpilor să fie din argint.", "La fel, pe latura de nord să fie pânze lungi de o sută de coți, cu douăzeci de stâlpi și douăzeci de socluri din bronz; cârligele și legăturile stâlpilor să fie din argint.", "Pe latura de apus, curtea să aibă pânze late de cincizeci de coți, cu zece stâlpi și zece socluri.", "Lățimea curții pe latura de răsărit să fie de cincizeci de coți.", "Pe o parte a intrării să fie pânze de cincisprezece coți, cu trei stâlpi și trei socluri.", "Pe cealaltă parte să fie pânze de cincisprezece coți, cu trei stâlpi și trei socluri.", "Pentru intrarea curții să fie un paravan lung de douăzeci de coți, din fir albastru, purpuriu și stacojiu și din in fin răsucit, lucrat prin broderie, cu patru stâlpi și patru socluri.", "Toți stâlpii curții să fie legați de jur împrejur cu argint; cârligele lor să fie din argint, iar soclurile din bronz.", "Curtea să fie lungă de o sută de coți, lată de cincizeci de coți pe toată întinderea și înaltă de cinci coți. Pânzele să fie din in fin răsucit, iar soclurile din bronz.", "Toate uneltele folosite în slujirea Cortului, toți țărușii lui și toți țărușii curții să fie din bronz.", "Să le poruncești fiilor lui Israel să-ți aducă ulei curat din măsline zdrobite pentru lumină, ca să ardă permanent candela.", "Aaron și fiii lui să o îngrijească de seara până dimineața înaintea DOMNULUI, în Cortul Întâlnirii, dincoace de perdeaua care este înaintea Mărturiei. Aceasta să fie o rânduială veșnică pentru fiii lui Israel, din generație în generație.”"],
    28: ["„Adu-i lângă tine, dintre fiii lui Israel, pe Aaron, fratele tău, și pe fiii lui — Nadab, Abihu, Eleazar și Itamar — ca Aaron să-Mi slujească în preoție.", "Să faci pentru Aaron, fratele tău, veșminte sfinte, pentru onoare și frumusețe.", "Să vorbești tuturor celor pricepuți la inimă, pe care i-am umplut cu duh de înțelepciune, ca să facă veșmintele lui Aaron, pentru a-l sfinți ca să-Mi slujească în preoție.", "Acestea sunt veșmintele pe care să le facă: un pieptar, un efod, o mantie, o tunică țesută, un turban și un brâu. Să facă veșminte sfinte pentru Aaron, fratele tău, și pentru fiii lui, ca să-Mi slujească în preoție.", "Să folosească aur, fir albastru, purpuriu și stacojiu și in fin.", "Să facă efodul din aur, din fir albastru, purpuriu și stacojiu și din in fin răsucit, lucrat artistic.", "Să aibă două bretele unite la cele două capete ale lui, ca să fie legat.", "Brâul țesut al efodului să fie lucrat la fel și dintr-o singură bucată cu el, din aur, fir albastru, purpuriu și stacojiu și in fin răsucit.", "Să iei două pietre de onix și să gravezi pe ele numele fiilor lui Israel:", "șase nume pe prima piatră și celelalte șase nume pe a doua piatră, în ordinea nașterii lor.", "Să gravezi pe cele două pietre numele fiilor lui Israel, prin lucrarea unui gravor în piatră, asemenea gravurii unui sigiliu, și să le montezi în monturi de aur.", "Să pui cele două pietre pe bretelele efodului, ca pietre de aducere-aminte pentru fiii lui Israel. Aaron să poarte numele lor pe cei doi umeri ai săi înaintea DOMNULUI, ca aducere-aminte.", "Să faci monturi de aur", "și două lănțișoare din aur curat, lucrate ca niște șnururi împletite, și să prinzi lănțișoarele împletite de monturi.", "Să faci pieptarul judecății, lucrat artistic. Să-l faci la fel ca efodul, din aur, fir albastru, purpuriu și stacojiu și din in fin răsucit.", "Să fie pătrat și îndoit în două, lung de o palmă și lat de o palmă.", "Să montezi în el patru rânduri de pietre. În primul rând: un rubin, un topaz și un smarald;", "în al doilea rând: un turcoaz, un safir și un diamant;", "în al treilea rând: un opal, un agat și un ametist;", "iar în al patrulea rând: un crisolit, un onix și un jasp. Pietrele să fie fixate în monturi de aur.", "Pietrele să fie douăsprezece, după numele fiilor lui Israel, câte una pentru fiecare nume. Fiecare să fie gravată asemenea unui sigiliu, cu numele uneia dintre cele douăsprezece seminții.", "Să faci pentru pieptar lănțișoare din aur curat, ca niște șnururi împletite.", "Să faci pentru pieptar două verigi de aur și să pui cele două verigi la cele două capete ale pieptarului.", "Să introduci cele două lănțișoare împletite din aur în cele două verigi de la capetele pieptarului.", "Celelalte două capete ale lănțișoarelor să le prinzi de cele două monturi și să le fixezi pe bretelele efodului, în partea din față.", "Să faci două verigi de aur și să le pui la celelalte două capete ale pieptarului, pe marginea lui dinspre partea interioară a efodului.", "Să mai faci două verigi de aur și să le pui pe cele două bretele ale efodului, în partea de jos și din față, aproape de locul unde se unesc, deasupra brâului țesut al efodului.", "Pieptarul să fie legat prin verigile lui de verigile efodului cu un șnur albastru, ca să rămână deasupra brâului țesut al efodului și să nu se desprindă de efod.", "Când va intra în Locul Sfânt, Aaron va purta pe inima sa numele fiilor lui Israel în pieptarul judecății, ca aducere-aminte permanentă înaintea DOMNULUI.", "Să pui în pieptarul judecății Urim și Tumim. Ele să fie pe inima lui Aaron când intră înaintea DOMNULUI. Aaron va purta permanent pe inima sa judecata fiilor lui Israel înaintea DOMNULUI.", "Să faci mantia efodului în întregime din fir albastru.", "Să aibă în mijloc o deschizătură pentru cap, iar în jurul deschizăturii să aibă o margine țesută, asemenea deschizăturii unei platoșe, ca să nu se rupă.", "Pe tivul ei să faci rodii din fir albastru, purpuriu și stacojiu, de jur împrejurul tivului, iar între ele clopoței de aur:", "un clopoțel de aur și o rodie, un clopoțel de aur și o rodie, de jur împrejurul tivului mantiei.", "Aaron să o poarte când slujește. Sunetul ei să se audă când intră în Locul Sfânt înaintea DOMNULUI și când iese, ca să nu moară.", "Să faci o plăcuță din aur curat și să gravezi pe ea, asemenea gravurii unui sigiliu: «SFÂNT PENTRU DOMNUL».", "Să o prinzi cu un șnur albastru pe turban; să fie în partea din față a turbanului.", "Ea să fie pe fruntea lui Aaron. Aaron va purta vina legată de lucrurile sfinte pe care fiii lui Israel le vor sfinți prin toate darurile lor sfinte. Ea să fie permanent pe fruntea lui, pentru ca ei să fie primiți înaintea DOMNULUI.", "Să țeseți tunica din in fin, să faci turbanul din in fin și să faci brâul lucrat prin broderie.", "Pentru fiii lui Aaron să faci tunici, brâie și bonete, pentru onoare și frumusețe.", "Să-i îmbraci cu ele pe Aaron, fratele tău, și pe fiii lui împreună cu el. Să-i ungi, să-i învestești, să-i sfințești, iar ei Îmi vor sluji în preoție.", "Să le faci pantaloni de in care să le acopere trupul gol, de la talie până la coapse.", "Aaron și fiii lui să-i poarte când intră în Cortul Întâlnirii sau când se apropie de altar ca să slujească în Locul Sfânt, ca să nu poarte vină și să moară. Aceasta să fie o rânduială veșnică pentru el și pentru urmașii lui.”"],
    29: ["„Iată ce să faci pentru a-i sfinți ca să-Mi slujească în preoție: ia un taur tânăr și doi berbeci fără cusur,", "pâine nedospită, turte nedospite frământate cu ulei și lipii nedospite unse cu ulei. Să le faci din făină fină de grâu.", "Să le pui într-un coș și să le aduci în coș împreună cu taurul și cei doi berbeci.", "Să-i aduci pe Aaron și pe fiii lui la intrarea Cortului Întâlnirii și să-i speli cu apă.", "Să iei veșmintele și să-l îmbraci pe Aaron cu tunica, mantia efodului, efodul și pieptarul și să-l încingi cu brâul țesut al efodului.", "Să-i pui turbanul pe cap și să fixezi pe turban coroana sfântă.", "Apoi să iei untdelemnul ungerii, să-l torni pe capul lui și să-l ungi.", "Să-i aduci pe fiii lui și să-i îmbraci cu tunicile.", "Să-i încingi cu brâiele, pe Aaron și pe fiii lui, și să le legi bonetele. Preoția va fi a lor printr-o rânduială veșnică. Astfel să-i învestești pe Aaron și pe fiii lui.", "Să aduci taurul înaintea Cortului Întâlnirii, iar Aaron și fiii lui să-și pună mâinile pe capul taurului.", "Să înjunghii taurul înaintea DOMNULUI, la intrarea Cortului Întâlnirii.", "Să iei din sângele taurului și să pui cu degetul pe coarnele altarului, iar tot sângele rămas să-l verși la baza altarului.", "Să iei toată grăsimea care acoperă măruntaiele, lobul ficatului, cei doi rinichi și grăsimea de pe ei și să le arzi pe altar.", "Dar carnea taurului, pielea și bălegarul lui să le arzi în foc în afara taberei. Este o jertfă pentru păcat.", "Să iei unul dintre berbeci, iar Aaron și fiii lui să-și pună mâinile pe capul berbecului.", "Să înjunghii berbecul, să-i iei sângele și să-l stropești de jur împrejur pe altar.", "Să tai berbecul în bucăți, să-i speli măruntaiele și picioarele și să le pui lângă bucăți și lângă cap.", "Să arzi întregul berbec pe altar. Este o ardere-de-tot pentru DOMNUL, o mireasmă plăcută, o jertfă mistuită de foc pentru DOMNUL.", "Să iei celălalt berbec, iar Aaron și fiii lui să-și pună mâinile pe capul berbecului.", "Să înjunghii berbecul și să pui din sângele lui pe lobul urechii drepte a lui Aaron și pe lobul urechii drepte a fiilor lui, pe degetul mare al mâinii lor drepte și pe degetul mare al piciorului lor drept. Să stropești sângele de jur împrejur pe altar.", "Să iei din sângele de pe altar și din untdelemnul ungerii și să stropești pe Aaron și veșmintele lui, pe fiii lui și veșmintele fiilor lui. Astfel vor fi sfințiți el, veșmintele lui, fiii lui și veșmintele fiilor lui.", "Să iei din grăsimea berbecului: coada grasă, grăsimea care acoperă măruntaiele, lobul ficatului, cei doi rinichi cu grăsimea de pe ei și pulpa dreaptă, căci este berbecul învestirii.", "Să iei și o pâine, o turtă făcută cu ulei și o lipie din coșul cu azime care este înaintea DOMNULUI.", "Să le pui pe toate în mâinile lui Aaron și în mâinile fiilor lui și să le legeni ca dar legănat înaintea DOMNULUI.", "Apoi să le iei din mâinile lor și să le arzi pe altar, deasupra arderii-de-tot, ca mireasmă plăcută înaintea DOMNULUI. Este o jertfă mistuită de foc pentru DOMNUL.", "Să iei pieptul berbecului învestirii lui Aaron și să-l legeni ca dar legănat înaintea DOMNULUI. Aceasta va fi partea ta.", "Să sfințești pieptul darului legănat și pulpa contribuției, care au fost legănate și ridicate din berbecul învestirii, din ceea ce este pentru Aaron și fiii lui.", "Ele vor fi partea lui Aaron și a fiilor lui din partea fiilor lui Israel, printr-o rânduială veșnică, fiindcă sunt o contribuție. Ele vor fi contribuția fiilor lui Israel din jertfele lor de pace, contribuția lor pentru DOMNUL.", "Veșmintele sfinte ale lui Aaron vor fi ale fiilor lui după el, ca să fie unși și învestiți în ele.", "Fiul care îi va urma ca preot să le poarte șapte zile când va intra în Cortul Întâlnirii ca să slujească în Locul Sfânt.", "Să iei berbecul învestirii și să-i fierbi carnea într-un loc sfânt.", "Aaron și fiii lui să mănânce carnea berbecului și pâinea din coș la intrarea Cortului Întâlnirii.", "Să mănânce lucrurile prin care s-a făcut ispășire pentru învestirea și sfințirea lor. Niciun străin să nu mănânce din ele, fiindcă sunt sfinte.", "Dacă rămâne până dimineață ceva din carnea învestirii sau din pâine, să arzi ce a rămas în foc. Să nu fie mâncat, fiindcă este sfânt.", "Să faci pentru Aaron și fiii lui tot ce ți-am poruncit. Timp de șapte zile să-i învestești.", "În fiecare zi să aduci un taur ca jertfă pentru păcat, pentru ispășire. Să cureți altarul făcând ispășire pentru el și să-l ungi ca să-l sfințești.", "Timp de șapte zile să faci ispășire pentru altar și să-l sfințești. Altarul va fi preasfânt; orice lucru care atinge altarul va deveni sfânt.", "Iată ce să aduci permanent pe altar: doi miei de un an, în fiecare zi.", "Un miel să-l aduci dimineața, iar pe celălalt miel spre seară.", "Împreună cu primul miel să aduci a zecea parte dintr-o efă de făină fină, amestecată cu un sfert de hin de ulei din măsline zdrobite, și un sfert de hin de vin ca dar de băutură.", "Pe al doilea miel să-l aduci spre seară, împreună cu un dar de mâncare și un dar de băutură ca dimineața, ca mireasmă plăcută, o jertfă mistuită de foc pentru DOMNUL.", "Aceasta să fie o ardere-de-tot permanentă din generație în generație, la intrarea Cortului Întâlnirii, înaintea DOMNULUI, unde Mă voi întâlni cu voi ca să-ți vorbesc.", "Acolo Mă voi întâlni cu fiii lui Israel, iar locul va fi sfințit prin gloria Mea.", "Voi sfinți Cortul Întâlnirii și altarul; îi voi sfinți și pe Aaron și pe fiii lui ca să-Mi slujească în preoție.", "Voi locui în mijlocul fiilor lui Israel și voi fi Dumnezeul lor.", "Ei vor ști că Eu sunt DOMNUL, Dumnezeul lor, Care i-am scos din țara Egiptului ca să locuiesc în mijlocul lor. Eu sunt DOMNUL, Dumnezeul lor.”"],
    30: ["„Să faci un altar pentru arderea tămâiei. Să-l faci din lemn de salcâm.", "Să fie lung de un cot, lat de un cot, pătrat, și înalt de doi coți. Coarnele lui să fie dintr-o singură bucată cu el.", "Să-i acoperi cu aur curat partea de sus, laturile și coarnele și să-i faci de jur împrejur un chenar de aur.", "Să-i faci două verigi de aur sub chenar, pe cele două laturi opuse, ca să țină drugii cu care va fi purtat.", "Să faci drugii din lemn de salcâm și să-i acoperi cu aur.", "Să așezi altarul înaintea perdelei care este lângă chivotul Mărturiei, înaintea capacului ispășirii care este deasupra Mărturiei, acolo unde Mă voi întâlni cu tine.", "Aaron să ardă pe el tămâie parfumată în fiecare dimineață, când îngrijește candelele.", "Să ardă tămâie și spre seară, când aprinde candelele. Aceasta să fie o tămâie permanentă înaintea DOMNULUI, din generație în generație.", "Să nu aduceți pe el tămâie neautorizată, ardere-de-tot sau dar de mâncare și să nu turnați pe el dar de băutură.", "O dată pe an, Aaron să facă ispășire pe coarnele altarului cu sângele jertfei pentru păcat aduse pentru ispășire. Să facă ispășire pentru el o dată pe an, din generație în generație. Altarul este preasfânt pentru DOMNUL.”", "DOMNUL i-a vorbit lui Moise și i-a spus:", "„Când îi vei număra pe fiii lui Israel printr-un recensământ, fiecare să-I dea DOMNULUI un preț de răscumpărare pentru viața lui când este numărat, ca să nu vină nicio lovitură peste ei în timpul numărătorii.", "Fiecare dintre cei care trec la numărătoare să dea o jumătate de șechel, după șechelul sanctuarului — șechelul are douăzeci de ghere — o jumătate de șechel drept contribuție pentru DOMNUL.", "Oricine trece la numărătoare, de la vârsta de douăzeci de ani în sus, să dea contribuția pentru DOMNUL.", "Bogatul să nu dea mai mult, iar săracul să nu dea mai puțin de o jumătate de șechel, când dați contribuția DOMNULUI ca să se facă ispășire pentru viețile voastre.", "Să iei argintul ispășirii de la fiii lui Israel și să-l folosești pentru slujirea Cortului Întâlnirii. El va fi pentru fiii lui Israel o aducere-aminte înaintea DOMNULUI, ca să se facă ispășire pentru viețile voastre.”", "DOMNUL i-a vorbit lui Moise și i-a spus:", "„Să faci un lighean din bronz, cu suportul lui din bronz, pentru spălare. Să-l pui între Cortul Întâlnirii și altar și să pui apă în el.", "Aaron și fiii lui să-și spele în el mâinile și picioarele.", "Când vor intra în Cortul Întâlnirii, să se spele cu apă ca să nu moară; la fel când se vor apropia de altar ca să slujească și să ardă o jertfă mistuită de foc pentru DOMNUL.", "Să-și spele mâinile și picioarele ca să nu moară. Aceasta să fie o rânduială veșnică pentru Aaron și pentru urmașii lui, din generație în generație.”", "DOMNUL i-a vorbit lui Moise și i-a spus:", "„Ia mirodenii de cea mai bună calitate: cinci sute de șecheli de smirnă lichidă, jumătate din această cantitate, adică două sute cincizeci de șecheli, de scorțișoară parfumată și două sute cincizeci de șecheli de trestie parfumată,", "cinci sute de șecheli de casia, după șechelul sanctuarului, și un hin de ulei de măsline.", "Să faci din ele un untdelemn sfânt pentru ungere, un amestec parfumat, lucrat de un făcător de parfumuri. Acesta va fi untdelemnul sfânt pentru ungere.", "Să ungi cu el Cortul Întâlnirii, chivotul Mărturiei,", "masa cu toate obiectele ei, sfeșnicul cu toate obiectele lui, altarul tămâierii,", "altarul arderii-de-tot cu toate uneltele lui și ligheanul cu suportul lui.", "Să le sfințești și ele vor fi preasfinte; orice lucru care le atinge va deveni sfânt.", "Să-i ungi pe Aaron și pe fiii lui și să-i sfințești ca să-Mi slujească în preoție.", "Să le vorbești fiilor lui Israel: «Acesta să fie pentru Mine un untdelemn sfânt pentru ungere, din generație în generație.", "Să nu fie turnat pe trupul niciunui om și să nu faceți altul cu aceeași compoziție. Este sfânt și să fie sfânt pentru voi.", "Oricine va prepara un amestec asemenea lui sau va pune din el pe o persoană neautorizată va fi îndepărtat din poporul său.»”", "DOMNUL i-a spus lui Moise: „Ia mirodenii parfumate: rășină, onicha și galban, mirodenii parfumate împreună cu tămâie curată, în cantități egale.", "Să faci din ele tămâie, un amestec parfumat lucrat de un făcător de parfumuri, sărat, curat și sfânt.", "Să pisezi o parte din ea foarte fin și să pui din ea înaintea Mărturiei, în Cortul Întâlnirii, acolo unde Mă voi întâlni cu tine. Ea să fie pentru voi preasfântă.", "Să nu vă faceți pentru voi tămâie cu aceeași compoziție; să o considerați sfântă pentru DOMNUL.", "Oricine va face una asemenea ei ca să-i simtă mirosul va fi îndepărtat din poporul său.”"],
    31: ["DOMNUL i-a vorbit lui Moise și i-a spus:", "„Iată, l-am chemat pe nume pe Bețaleel, fiul lui Uri, fiul lui Hur, din seminția lui Iuda.", "L-am umplut cu Duhul lui Dumnezeu, cu înțelepciune, pricepere, cunoaștere și îndemânare în orice meșteșug,", "ca să conceapă lucrări artistice și să lucreze în aur, argint și bronz,", "să taie pietre pentru montare, să cioplească lemnul și să lucreze în orice meșteșug.", "Iată, l-am rânduit împreună cu el pe Oholiab, fiul lui Ahisamac, din seminția lui Dan. Am pus înțelepciune în inima tuturor celor pricepuți, ca să facă tot ce ți-am poruncit:", "Cortul Întâlnirii, chivotul Mărturiei, capacul ispășirii care este deasupra lui și toate obiectele Cortului,", "masa cu obiectele ei, sfeșnicul curat cu toate obiectele lui, altarul tămâierii,", "altarul arderii-de-tot cu toate uneltele lui și ligheanul cu suportul său,", "veșmintele lucrate pentru slujire, veșmintele sfinte ale preotului Aaron și veșmintele fiilor lui pentru slujirea preoțească,", "untdelemnul ungerii și tămâia parfumată pentru Locul Sfânt. Ei să facă totul după cum ți-am poruncit.”", "DOMNUL i-a vorbit lui Moise și i-a spus:", "„Vorbește-le și fiilor lui Israel: «Să păziți cu grijă Sabaturile Mele, căci acesta este un semn între Mine și voi din generație în generație, ca să știți că Eu sunt DOMNUL, Cel care vă sfințește.", "Să păziți Sabatul, căci este sfânt pentru voi. Cine îl profanează să fie omorât; oricine face muncă în ziua aceea va fi îndepărtat din mijlocul poporului său.", "Șase zile să se lucreze, dar ziua a șaptea este un Sabat de odihnă deplină, sfânt pentru DOMNUL. Oricine face muncă în ziua Sabatului să fie omorât.", "Fiii lui Israel să păzească Sabatul, ținând Sabatul din generație în generație ca legământ veșnic.", "El este un semn pentru totdeauna între Mine și fiii lui Israel, căci în șase zile DOMNUL a făcut cerurile și pământul, iar în ziua a șaptea S-a oprit și S-a înviorat.»”", "Când a terminat de vorbit cu Moise pe muntele Sinai, Dumnezeu i-a dat cele două table ale Mărturiei, table de piatră scrise cu degetul lui Dumnezeu."],
    32: ["Când poporul a văzut că Moise întârzia să coboare de pe munte, s-a strâns în jurul lui Aaron și i-a spus: „Ridică-te și fă-ne dumnezei care să meargă înaintea noastră, căci nu știm ce s-a întâmplat cu acest Moise, omul care ne-a scos din țara Egiptului.”", "Aaron le-a spus: „Scoateți cerceii de aur din urechile soțiilor, fiilor și fiicelor voastre și aduceți-i la mine.”", "Tot poporul și-a scos cerceii de aur din urechi și i-a adus lui Aaron.", "El a luat aurul din mâinile lor, i-a dat formă cu o unealtă și a făcut un vițel turnat. Ei au spus: „Aceștia sunt dumnezeii tăi, Israel, care te-au scos din țara Egiptului!”", "Când Aaron a văzut aceasta, a construit un altar înaintea vițelului și a vestit: „Mâine va fi o sărbătoare pentru DOMNUL.”", "A doua zi s-au sculat devreme, au adus arderi-de-tot și jertfe de pace. Poporul s-a așezat să mănânce și să bea, apoi s-a ridicat să petreacă.", "DOMNUL i-a spus lui Moise: „Coboară, căci poporul tău, pe care l-ai scos din țara Egiptului, s-a corupt.", "S-au abătut repede de la calea pe care le-am poruncit-o. Și-au făcut un vițel turnat, s-au plecat înaintea lui, i-au adus jertfe și au spus: «Aceștia sunt dumnezeii tăi, Israel, care te-au scos din țara Egiptului!»”", "DOMNUL i-a mai spus lui Moise: „Am văzut poporul acesta și iată că este un popor cu gâtul înțepenit.", "Acum lasă-Mă! Mânia Mea se va aprinde împotriva lor și îi voi nimici, iar din tine voi face un popor mare.”", "Dar Moise a căutat bunăvoința DOMNULUI, Dumnezeul său, și a spus: „DOMNULE, de ce să se aprindă mânia Ta împotriva poporului Tău, pe care l-ai scos din țara Egiptului cu putere mare și cu mână tare?", "De ce să spună egiptenii: «Cu intenție rea i-a scos, ca să-i omoare în munți și să-i șteargă de pe fața pământului»? Întoarce-Te de la mânia Ta aprinsă și renunță la nenorocirea hotărâtă împotriva poporului Tău.", "Adu-Ți aminte de Avraam, Isaac și Israel, slujitorii Tăi, cărora le-ai jurat pe Tine Însuți: «Voi înmulți urmașii voștri ca stelele cerului și voi da urmașilor voștri toată țara despre care am vorbit, iar ei o vor moșteni pentru totdeauna.»”", "Atunci DOMNUL a renunțat la nenorocirea despre care spusese că o va aduce asupra poporului Său.", "Moise s-a întors și a coborât de pe munte, având în mâini cele două table ale Mărturiei, table scrise pe ambele părți, pe o parte și pe cealaltă.", "Tablele erau lucrarea lui Dumnezeu, iar scrierea era scrierea lui Dumnezeu, gravată pe table.", "Când Iosua a auzit glasul poporului care striga, i-a spus lui Moise: „Se aude zgomot de război în tabără!”", "Moise a răspuns: „Nu este glas de strigăt al biruitorilor și nici glas de strigăt al învinșilor; eu aud glas de cântare.”", "Când s-a apropiat de tabără și a văzut vițelul și dansurile, mânia lui Moise s-a aprins. A aruncat tablele din mâini și le-a sfărâmat la poalele muntelui.", "A luat vițelul pe care îl făcuseră, l-a ars în foc, l-a măcinat până s-a făcut pulbere, a presărat pulberea pe apă și i-a pus pe fiii lui Israel să o bea.", "Moise i-a spus lui Aaron: „Ce ți-a făcut poporul acesta de ai adus asupra lui un păcat atât de mare?”", "Aaron a răspuns: „Să nu se aprindă mânia stăpânului meu! Tu știi că poporul este înclinat spre rău.", "Ei mi-au spus: «Fă-ne dumnezei care să meargă înaintea noastră, căci nu știm ce s-a întâmplat cu acest Moise, omul care ne-a scos din țara Egiptului.»", "Eu le-am spus: «Cine are aur să-l scoată.» Mi l-au dat, eu l-am aruncat în foc și a ieșit vițelul acesta.”", "Moise a văzut că poporul scăpase de sub control, căci Aaron îl lăsase fără frâu, spre batjocura dușmanilor lui.", "Atunci Moise s-a așezat la intrarea taberei și a spus: „Cine este de partea DOMNULUI să vină la mine!” Toți fiii lui Levi s-au strâns în jurul lui.", "El le-a spus: „Așa vorbește DOMNUL, Dumnezeul lui Israel: «Fiecare să-și pună sabia la coapsă. Treceți și întoarceți-vă prin tabără, de la o intrare la alta, și fiecare să-l omoare pe fratele său, pe prietenul său și pe semenul său.»”", "Fiii lui Levi au făcut după cuvântul lui Moise, iar în ziua aceea au căzut din popor aproximativ trei mii de bărbați.", "Moise a spus: „Astăzi v-ați învestit pentru DOMNUL, fiecare cu prețul fiului și al fratelui său, pentru ca El să vă dea astăzi o binecuvântare.”", "A doua zi, Moise a spus poporului: „Ați comis un păcat mare. Acum mă voi urca la DOMNUL; poate voi putea face ispășire pentru păcatul vostru.”", "Moise s-a întors la DOMNUL și a spus: „O, poporul acesta a comis un păcat mare și și-a făcut dumnezei de aur!", "Acum, Te rog, iartă-le păcatul! Dacă nu, șterge-mă, Te rog, din cartea Ta pe care ai scris-o.”", "DOMNUL i-a spus lui Moise: „Pe cel care a păcătuit împotriva Mea îl voi șterge din cartea Mea.", "Acum du-te și condu poporul spre locul despre care ți-am vorbit. Iată, Îngerul Meu va merge înaintea ta. Dar în ziua când voi cerceta, îi voi pedepsi pentru păcatul lor.”", "DOMNUL a lovit poporul din cauza vițelului pe care îl făcuseră, vițelul făcut de Aaron."],
    33: ["DOMNUL i-a spus lui Moise: „Pleacă și urcă de aici, tu și poporul pe care l-ai scos din țara Egiptului, spre țara despre care le-am jurat lui Avraam, Isaac și Iacov: «O voi da urmașilor voștri.»", "Voi trimite înaintea ta un înger și îi voi izgoni pe canaaniți, amoriți, hetiți, periziți, heviți și iebusiți.", "Urcă spre țara în care curge lapte și miere. Dar Eu nu voi urca în mijlocul tău, pentru că ești un popor cu gâtul înțepenit, ca să nu te nimicesc pe drum.”", "Când poporul a auzit această veste rea, a început să jelească și nimeni nu și-a pus podoabele.", "DOMNUL îi spusese lui Moise: „Spune-le fiilor lui Israel: «Sunteți un popor cu gâtul înțepenit. Dacă aș urca o singură clipă în mijlocul vostru, v-aș nimici. Acum scoateți-vă podoabele, iar Eu voi hotărî ce să fac cu voi.»”", "Astfel, fiii lui Israel și-au scos podoabele de la muntele Horeb înainte.", "Moise obișnuia să ia un cort și să-l ridice în afara taberei, departe de tabără, și îl numea Cortul Întâlnirii. Oricine Îl căuta pe DOMNUL ieșea la Cortul Întâlnirii, care era în afara taberei.", "Când Moise ieșea spre Cort, tot poporul se ridica și fiecare stătea la intrarea cortului său, urmărindu-l pe Moise până când intra în Cort.", "Când Moise intra în Cort, stâlpul de nor cobora și se oprea la intrarea Cortului, iar DOMNUL vorbea cu Moise.", "Tot poporul vedea stâlpul de nor oprit la intrarea Cortului. Atunci tot poporul se ridica și fiecare se închina la intrarea cortului său.", "DOMNUL vorbea cu Moise față în față, așa cum vorbește un om cu prietenul său. Apoi Moise se întorcea în tabără, dar slujitorul lui, Iosua, fiul lui Nun, un tânăr, nu se îndepărta din Cort.", "Moise I-a spus DOMNULUI: „Iată, Tu îmi spui: «Condu poporul acesta», dar nu mi-ai făcut cunoscut pe cine vei trimite împreună cu mine. Totuși, ai spus: «Te cunosc pe nume și ai găsit bunăvoință în ochii Mei.»", "Acum, dacă am găsit bunăvoință în ochii Tăi, fă-mi cunoscute, Te rog, căile Tale, ca să Te cunosc și să găsesc în continuare bunăvoință în ochii Tăi. Privește că poporul acesta este poporul Tău.”", "DOMNUL a răspuns: „Prezența Mea va merge cu tine și îți voi da odihnă.”", "Moise I-a spus: „Dacă Prezența Ta nu merge cu noi, nu ne face să plecăm de aici.", "Prin ce se va cunoaște că eu și poporul Tău am găsit bunăvoință în ochii Tăi? Nu prin faptul că mergi cu noi, astfel încât eu și poporul Tău să fim deosebiți de toate popoarele de pe fața pământului?”", "DOMNUL i-a spus lui Moise: „Voi face și lucrul acesta pe care l-ai cerut, căci ai găsit bunăvoință în ochii Mei și te cunosc pe nume.”", "Moise a spus: „Arată-mi, Te rog, gloria Ta!”", "DOMNUL a răspuns: „Voi face să treacă înaintea ta toată bunătatea Mea și voi proclama înaintea ta Numele DOMNULUI. Voi arăta har cui voi arăta har și voi avea milă de cine voi avea milă.”", "El a mai spus: „Nu poți să-Mi vezi fața, căci omul nu Mă poate vedea și să trăiască.”", "DOMNUL a spus: „Iată un loc lângă Mine; să stai pe stâncă.", "Când va trece gloria Mea, te voi pune într-o crăpătură a stâncii și te voi acoperi cu mâna Mea până voi trece.", "Apoi Îmi voi lua mâna și Mă vei vedea din urmă, dar fața Mea nu va fi văzută.”"],
    34: ["DOMNUL i-a spus lui Moise: „Cioplește două table de piatră asemenea celor dintâi. Eu voi scrie pe table cuvintele care erau pe primele table, pe care le-ai sfărâmat.", "Fii gata dimineață. Urcă dimineață pe muntele Sinai și înfățișează-te înaintea Mea acolo, pe vârful muntelui.", "Nimeni să nu urce împreună cu tine și nimeni să nu fie văzut pe tot muntele. Nici turmele, nici cirezile să nu pască înaintea muntelui.”", "Moise a cioplit două table de piatră asemenea celor dintâi. S-a sculat dis-de-dimineață și s-a urcat pe muntele Sinai, așa cum îi poruncise DOMNUL, având în mână cele două table de piatră.", "DOMNUL a coborât în nor, a stat acolo împreună cu el și a proclamat Numele DOMNULUI.", "DOMNUL a trecut pe dinaintea lui și a proclamat: „DOMNUL! DOMNUL! Dumnezeu milos și plin de har, încet la mânie, bogat în bunătate statornică și credincioșie,", "Care păstrează bunătatea statornică pentru mii, iartă nelegiuirea, răzvrătirea și păcatul, dar nu-l declară nevinovat pe cel vinovat; cercetează vina părinților în copii și în copiii copiilor, până la a treia și a patra generație.”", "Moise s-a grăbit, s-a plecat cu fața la pământ și s-a închinat.", "El a spus: „Stăpâne, dacă am găsit bunăvoință în ochii Tăi, Te rog să mergi în mijlocul nostru, chiar dacă este un popor cu gâtul înțepenit. Iartă nelegiuirea și păcatul nostru și ia-ne ca moștenire a Ta.”", "DOMNUL a răspuns: „Iată, închei un legământ. Înaintea întregului tău popor voi face minuni cum nu s-au mai făcut în tot pământul și în nicio națiune. Tot poporul în mijlocul căruia te afli va vedea lucrarea DOMNULUI, căci înfricoșător este ceea ce voi face cu tine.", "Păzește ceea ce îți poruncesc astăzi. Iată, îi voi izgoni dinaintea ta pe amoriți, canaaniți, hetiți, periziți, heviți și iebusiți.", "Ai grijă să nu închei legământ cu locuitorii țării în care mergi, ca să nu devină o cursă în mijlocul tău.", "Dimpotrivă, să le dărâmați altarele, să le sfărâmați stâlpii sacri și să le tăiați așerele.", "Să nu te închini altui dumnezeu, căci DOMNUL, al Cărui Nume este Gelos, este un Dumnezeu gelos.", "Să nu închei legământ cu locuitorii țării, ca nu cumva, prostituându-se după dumnezeii lor și aducând jertfe dumnezeilor lor, cineva să te invite și tu să mănânci din jertfa lui.", "Să nu iei dintre fiicele lor pentru fiii tăi, ca nu cumva fiicele lor, prostituându-se după dumnezeii lor, să-i facă și pe fiii tăi să se prostitueze după dumnezeii lor.", "Să nu-ți faci dumnezei turnați.", "Să păzești Sărbătoarea Azimelor. Timp de șapte zile să mănânci azime, așa cum ți-am poruncit, la timpul hotărât în luna Abib, căci în luna Abib ai ieșit din Egipt.", "Orice întâi venit care deschide pântecele este al Meu, precum și orice întâi născut de parte bărbătească al vitelor și oilor tale.", "Să răscumperi întâiul născut al măgăriței cu un animal din turmă, iar dacă nu-l răscumperi, să-i frângi gâtul. Să răscumperi orice întâi născut dintre fiii tăi. Nimeni să nu se înfățișeze înaintea Mea cu mâna goală.", "Șase zile să lucrezi, dar în ziua a șaptea să te odihnești; chiar și în timpul aratului și al secerișului să te odihnești.", "Să păzești Sărbătoarea Săptămânilor, cu primele roade ale secerișului grâului, și Sărbătoarea Strângerii Roadelor la încheierea anului.", "De trei ori pe an, toți bărbații tăi să se înfățișeze înaintea Stăpânului, DOMNUL, Dumnezeul lui Israel.", "Căci voi izgoni națiunile dinaintea ta și îți voi lărgi hotarele. Nimeni nu-ți va pofti țara când te vei urca să te înfățișezi înaintea DOMNULUI, Dumnezeul tău, de trei ori pe an.", "Să nu aduci sângele jertfei Mele împreună cu pâine dospită, iar jertfa Sărbătorii Paștelui să nu rămână până dimineață.", "Să aduci cele dintâi dintre primele roade ale pământului tău în Casa DOMNULUI, Dumnezeul tău. Să nu fierbi un ied în laptele mamei sale.”", "DOMNUL i-a spus lui Moise: „Scrie aceste cuvinte, căci pe temeiul acestor cuvinte am încheiat un legământ cu tine și cu Israel.”", "Moise a rămas acolo cu DOMNUL patruzeci de zile și patruzeci de nopți. Nu a mâncat pâine și nu a băut apă. A scris pe table cuvintele legământului, Cele Zece Cuvinte.", "Când Moise a coborât de pe muntele Sinai, având în mână cele două table ale Mărturiei, nu știa că pielea feței lui strălucea pentru că vorbise cu Dumnezeu.", "Aaron și toți fiii lui Israel l-au văzut pe Moise și iată că pielea feței lui strălucea, iar ei s-au temut să se apropie de el.", "Moise i-a chemat, iar Aaron și toate căpeteniile comunității s-au întors la el. Moise le-a vorbit.", "După aceea s-au apropiat toți fiii lui Israel, iar el le-a poruncit tot ce îi spusese DOMNUL pe muntele Sinai.", "Când Moise a terminat de vorbit cu ei, și-a pus o învelitoare pe față.", "Ori de câte ori Moise intra înaintea DOMNULUI ca să vorbească cu El, își scotea învelitoarea până când ieșea. Când ieșea, le spunea fiilor lui Israel ce îi fusese poruncit.", "Fiii lui Israel vedeau că pielea feței lui Moise strălucea. Atunci Moise își punea din nou învelitoarea pe față până când intra să vorbească cu Dumnezeu."],
    35: ["Moise a adunat întreaga comunitate a fiilor lui Israel și le-a spus: „Acestea sunt lucrurile pe care DOMNUL a poruncit să le faceți:", "Șase zile să se lucreze, dar ziua a șaptea să fie pentru voi o zi sfântă, un Sabat de odihnă deplină pentru DOMNUL. Oricine face muncă în ziua aceea să fie omorât.", "Să nu aprindeți foc în niciuna dintre locuințele voastre în ziua Sabatului.”", "Moise a vorbit întregii comunități a fiilor lui Israel și a spus: „Iată ce a poruncit DOMNUL:", "Luați dintre bunurile voastre o contribuție pentru DOMNUL. Oricine are inima binevoitoare să aducă drept contribuție pentru DOMNUL aur, argint și bronz,", "fir albastru, purpuriu și stacojiu, in fin, păr de capră,", "piei de berbec vopsite în roșu, piei fine și lemn de salcâm,", "ulei pentru lumină, mirodenii pentru untdelemnul ungerii și pentru tămâia parfumată,", "pietre de onix și pietre de montat pentru efod și pieptar.", "Toți cei pricepuți dintre voi să vină și să facă tot ce a poruncit DOMNUL:", "Cortul, acoperământul și învelișul lui, copcile, scândurile, drugii, stâlpii și soclurile lui;", "chivotul cu drugii lui, capacul ispășirii și perdeaua despărțitoare;", "masa cu drugii și toate obiectele ei și pâinea Prezenței;", "sfeșnicul pentru lumină cu obiectele, candelele și uleiul lui;", "altarul tămâierii cu drugii lui, untdelemnul ungerii, tămâia parfumată și paravanul de la intrarea Cortului;", "altarul arderii-de-tot cu grătarul lui de bronz, drugii și toate uneltele lui, ligheanul și suportul lui;", "pânzele curții, stâlpii, soclurile și paravanul de la intrarea curții;", "țărușii Cortului, țărușii curții și funiile lor;", "veșmintele lucrate pentru slujirea în Locul Sfânt, veșmintele sfinte ale preotului Aaron și veșmintele fiilor lui pentru slujirea preoțească.”", "Întreaga comunitate a fiilor lui Israel a plecat dinaintea lui Moise.", "Apoi au venit toți cei a căror inimă îi îndemna și al căror duh îi făcea binevoitori și au adus contribuția DOMNULUI pentru lucrarea Cortului Întâlnirii, pentru întreaga lui slujire și pentru veșmintele sfinte.", "Au venit atât bărbați, cât și femei, toți cei cu inimă binevoitoare, și au adus broșe, cercei, inele, brățări și tot felul de obiecte de aur. Fiecare a adus un dar de aur pentru DOMNUL.", "Oricine avea fir albastru, purpuriu sau stacojiu, in fin, păr de capră, piei de berbec vopsite în roșu sau piei fine le-a adus.", "Oricine aducea o contribuție de argint sau de bronz a adus-o ca dar pentru DOMNUL, iar oricine avea lemn de salcâm potrivit pentru vreo lucrare a slujirii l-a adus.", "Toate femeile pricepute au tors cu mâinile lor și au adus ce torseseră: fir albastru, purpuriu și stacojiu și in fin.", "Toate femeile a căror inimă le îndemna prin pricepere au tors păr de capră.", "Conducătorii au adus pietrele de onix, pietrele de montat pentru efod și pieptar,", "mirodeniile și uleiul pentru lumină, pentru untdelemnul ungerii și pentru tămâia parfumată.", "Toți bărbații și toate femeile dintre fiii lui Israel a căror inimă îi făcea binevoitori să aducă pentru întreaga lucrare pe care DOMNUL poruncise prin Moise să fie făcută au adus DOMNULUI un dar de bunăvoie.", "Moise le-a spus fiilor lui Israel: „Vedeți, DOMNUL l-a chemat pe nume pe Bețaleel, fiul lui Uri, fiul lui Hur, din seminția lui Iuda.", "L-a umplut cu Duhul lui Dumnezeu, cu înțelepciune, pricepere, cunoaștere și îndemânare în orice meșteșug,", "ca să conceapă lucrări artistice și să lucreze în aur, argint și bronz,", "să taie pietre pentru montare, să cioplească lemnul și să lucreze în orice meșteșug artistic.", "Dumnezeu a pus în inima lui și în a lui Oholiab, fiul lui Ahisamac, din seminția lui Dan, capacitatea de a-i învăța și pe alții.", "I-a umplut cu pricepere la inimă pentru a face orice lucrare de gravor, artist, broder în fir albastru, purpuriu și stacojiu și în in fin, țesător și creator de lucrări artistice.”"],
    36: ["„Bețaleel, Oholiab și fiecare om priceput, în care DOMNUL a pus înțelepciune și pricepere ca să știe să facă toată lucrarea pentru slujirea sanctuarului, să lucreze după tot ce a poruncit DOMNUL.”", "Moise i-a chemat pe Bețaleel, Oholiab și pe fiecare om priceput în a cărui inimă pusese DOMNUL înțelepciune, pe oricine era îndemnat de inimă să vină și să facă lucrarea.", "Ei au primit de la Moise toate contribuțiile pe care le aduseseră fiii lui Israel pentru lucrarea de construire și slujire a sanctuarului. Poporul continua să-i aducă lui Moise daruri de bunăvoie în fiecare dimineață.", "Atunci toți meșteșugarii pricepuți care făceau lucrarea sanctuarului și-au lăsat fiecare lucrarea.", "și au venit să-i spună lui Moise: „Poporul aduce mult mai mult decât este necesar pentru lucrarea pe care DOMNUL a poruncit să fie făcută.”", "Moise a dat o poruncă și s-a făcut următoarea vestire prin tabără: „Niciun bărbat și nicio femeie să nu mai pregătească nimic drept contribuție pentru sanctuar.” Astfel, poporul a fost oprit să mai aducă.", "Materialul era suficient pentru întreaga lucrare și chiar prisosea.", "Toți cei pricepuți dintre cei care făceau lucrarea au făcut Cortul din zece pânze de in fin răsucit și din fir albastru, purpuriu și stacojiu, cu heruvimi lucrați artistic.", "Fiecare pânză era lungă de douăzeci și opt de coți și lată de patru coți; toate pânzele aveau aceeași măsură.", "Au unit cinci pânze una de alta și celelalte cinci pânze una de alta.", "Au făcut cheotori din fir albastru pe marginea pânzei de la capătul primei îmbinări și la fel pe marginea pânzei de la capătul celei de-a doua îmbinări.", "Au făcut cincizeci de cheotori pe prima pânză și cincizeci de cheotori pe marginea pânzei din a doua îmbinare. Cheotorile erau așezate față în față.", "Au făcut cincizeci de copci de aur și au unit pânzele una cu alta prin copci, astfel încât Cortul a devenit un singur întreg.", "Au făcut unsprezece pânze din păr de capră, ca acoperământ peste Cort.", "Fiecare pânză era lungă de treizeci de coți și lată de patru coți; toate cele unsprezece pânze aveau aceeași măsură.", "Au unit separat cinci pânze și separat șase pânze.", "Au făcut cincizeci de cheotori pe marginea pânzei de la capătul primei îmbinări și cincizeci de cheotori pe marginea pânzei de la capătul celei de-a doua îmbinări.", "Au făcut cincizeci de copci din bronz pentru a uni acoperământul într-un singur întreg.", "Au făcut pentru cort un înveliș din piei de berbec vopsite în roșu și, deasupra lui, un înveliș din piei fine.", "Au făcut scândurile Cortului din lemn de salcâm și le-au așezat în picioare.", "Fiecare scândură era lungă de zece coți și lată de un cot și jumătate.", "Fiecare scândură avea două cepuri paralele. Așa au făcut toate scândurile Cortului.", "Au făcut douăzeci de scânduri pentru latura de sud a Cortului.", "și patruzeci de socluri de argint sub cele douăzeci de scânduri: două socluri sub fiecare scândură, pentru cele două cepuri ale ei.", "Pentru a doua latură a Cortului, cea de nord, au făcut douăzeci de scânduri.", "și patruzeci de socluri de argint, câte două socluri sub fiecare scândură.", "Pentru partea din spate a Cortului, spre apus, au făcut șase scânduri.", "Au făcut încă două scânduri pentru colțurile din spate ale Cortului.", "Ele erau duble în partea de jos și unite până sus, la primul inel. Așa au fost făcute amândouă, pentru cele două colțuri.", "Erau opt scânduri cu șaisprezece socluri de argint, câte două socluri sub fiecare scândură.", "Au făcut drugi din lemn de salcâm: cinci pentru scândurile de pe o latură a Cortului,", "cinci pentru scândurile de pe cealaltă latură și cinci pentru scândurile din partea din spate, spre apus.", "Au făcut drugul din mijloc să treacă prin mijlocul scândurilor de la un capăt la celălalt.", "Au acoperit scândurile cu aur, le-au făcut inele de aur prin care să treacă drugii și au acoperit drugii cu aur.", "Au făcut perdeaua din fir albastru, purpuriu și stacojiu și din in fin răsucit, cu heruvimi lucrați artistic.", "Au făcut pentru ea patru stâlpi din lemn de salcâm, i-au acoperit cu aur și le-au făcut cârlige din aur; pentru ei au turnat patru socluri de argint.", "Pentru intrarea cortului au făcut un paravan din fir albastru, purpuriu și stacojiu și din in fin răsucit, lucrat prin broderie,", "împreună cu cei cinci stâlpi și cârligele lor. Au acoperit cu aur capitelurile și legăturile stâlpilor, iar cele cinci socluri ale lor erau din bronz."],
    37: ["Bețaleel a făcut chivotul din lemn de salcâm, lung de doi coți și jumătate, lat de un cot și jumătate și înalt de un cot și jumătate.", "L-a acoperit cu aur curat pe dinăuntru și pe dinafară și i-a făcut de jur împrejur un chenar de aur.", "A turnat pentru el patru verigi de aur și le-a fixat la cele patru picioare: două verigi pe o latură și două pe cealaltă latură.", "A făcut drugi din lemn de salcâm și i-a acoperit cu aur.", "A introdus drugii în verigile de pe laturile chivotului, pentru a purta chivotul.", "A făcut capacul ispășirii din aur curat, lung de doi coți și jumătate și lat de un cot și jumătate.", "A făcut doi heruvimi din aur bătut, la cele două capete ale capacului ispășirii:", "un heruvim la un capăt și un heruvim la celălalt capăt; i-a făcut dintr-o singură bucată cu capacul, la cele două capete ale lui.", "Heruvimii își întindeau aripile în sus, acoperind cu aripile lor capacul ispășirii. Fețele lor erau îndreptate una spre alta și spre capacul ispășirii.", "A făcut masa din lemn de salcâm, lungă de doi coți, lată de un cot și înaltă de un cot și jumătate.", "A acoperit-o cu aur curat și i-a făcut de jur împrejur un chenar de aur.", "I-a făcut de jur împrejur o margine lată de o palmă și un chenar de aur în jurul marginii.", "A turnat pentru ea patru verigi de aur și a pus verigile în cele patru colțuri, la cele patru picioare ale mesei.", "Verigile erau lângă margine, ca locașuri pentru drugii cu care se purta masa.", "A făcut drugii din lemn de salcâm, i-a acoperit cu aur și masa era purtată cu ei.", "A făcut din aur curat obiectele de pe masă: farfuriile, lingurile, bolurile și cănile folosite la turnarea darurilor de băutură.", "A făcut sfeșnicul din aur curat, lucrat prin batere. Baza, tija, cupele, bobocii și florile lui erau dintr-o singură bucată cu el.", "Șase brațe ieșeau din laturile lui: trei brațe dintr-o latură și trei din cealaltă latură.", "Pe primul braț erau trei cupe în formă de floare de migdal, fiecare cu boboc și floare, și trei cupe în formă de floare de migdal pe brațul următor, fiecare cu boboc și floare; la fel pentru cele șase brațe care ieșeau din sfeșnic.", "Pe tija sfeșnicului erau patru cupe în formă de floare de migdal, cu bobocii și florile lor.", "Era un boboc sub prima pereche de brațe, un boboc sub a doua pereche și un boboc sub a treia pereche, pentru cele șase brațe care ieșeau din el.", "Bobocii și brațele erau dintr-o singură bucată cu el; întregul era o singură lucrare din aur curat, bătut.", "A făcut din aur curat cele șapte candele, cleștii pentru fitil și tăvițele lui.", "A făcut sfeșnicul și toate obiectele lui dintr-un talant de aur curat.", "A făcut altarul tămâierii din lemn de salcâm, lung de un cot, lat de un cot, pătrat, și înalt de doi coți. Coarnele lui erau dintr-o singură bucată cu el.", "I-a acoperit cu aur curat partea de sus, laturile și coarnele și i-a făcut de jur împrejur un chenar de aur.", "I-a făcut două verigi de aur sub chenar, pe cele două laturi opuse, ca să țină drugii cu care era purtat.", "A făcut drugii din lemn de salcâm și i-a acoperit cu aur.", "A făcut untdelemnul sfânt pentru ungere și tămâia parfumată curată, după meșteșugul făcătorului de parfumuri."],
    38: ["A făcut altarul arderii-de-tot din lemn de salcâm, lung de cinci coți, lat de cinci coți, pătrat, și înalt de trei coți.", "I-a făcut coarne la cele patru colțuri; coarnele erau dintr-o singură bucată cu el. L-a acoperit cu bronz.", "A făcut toate uneltele altarului: vasele pentru cenușă, lopețile, lighenele, furculițele și fărașele pentru cărbuni. Toate uneltele lui le-a făcut din bronz.", "A făcut pentru altar un grătar ca o rețea din bronz, sub marginea altarului, în partea de jos, până la jumătatea lui.", "A turnat patru verigi pentru cele patru colțuri ale grătarului de bronz, ca să țină drugii.", "A făcut drugii din lemn de salcâm și i-a acoperit cu bronz.", "A introdus drugii în verigile de pe laturile altarului, pentru a-l purta cu ei. A făcut altarul gol pe dinăuntru, din scânduri.", "A făcut ligheanul și suportul lui din bronz, folosind oglinzile femeilor care slujeau la intrarea Cortului Întâlnirii.", "A făcut curtea. Pe latura de sud, pânzele curții din in fin răsucit aveau o sută de coți.", "Erau douăzeci de stâlpi cu douăzeci de socluri din bronz; cârligele și legăturile stâlpilor erau din argint.", "Pe latura de nord, pânzele aveau o sută de coți, cu douăzeci de stâlpi și douăzeci de socluri din bronz; cârligele și legăturile stâlpilor erau din argint.", "Pe latura de apus, pânzele aveau cincizeci de coți, cu zece stâlpi și zece socluri; cârligele și legăturile stâlpilor erau din argint.", "Latura de răsărit avea cincizeci de coți.", "Pe o parte a intrării erau pânze de cincisprezece coți, cu trei stâlpi și trei socluri.", "La fel era pe cealaltă parte; de o parte și de alta a intrării curții erau pânze de cincisprezece coți, cu trei stâlpi și trei socluri.", "Toate pânzele din jurul curții erau din in fin răsucit.", "Soclurile stâlpilor erau din bronz, iar cârligele și legăturile stâlpilor din argint. Capitelurile lor erau acoperite cu argint și toți stâlpii curții erau legați cu argint.", "Paravanul de la intrarea curții era lucrat prin broderie, din fir albastru, purpuriu și stacojiu și din in fin răsucit. Era lung de douăzeci de coți și înalt de cinci coți, asemenea pânzelor curții.", "Avea patru stâlpi cu patru socluri din bronz; cârligele, învelișul capitelurilor și legăturile lor erau din argint.", "Toți țărușii Cortului și ai curții din jur erau din bronz.", "Acestea sunt cantitățile materialelor folosite pentru Cort, Cortul Mărturiei, numărate după porunca lui Moise pentru slujirea leviților, sub conducerea lui Itamar, fiul preotului Aaron.", "Bețaleel, fiul lui Uri, fiul lui Hur, din seminția lui Iuda, a făcut tot ce îi poruncise DOMNUL lui Moise.", "Împreună cu el a lucrat Oholiab, fiul lui Ahisamac, din seminția lui Dan, gravor, artist și broder în fir albastru, purpuriu și stacojiu și în in fin.", "Tot aurul folosit pentru întreaga lucrare a sanctuarului, aurul contribuției, a fost de douăzeci și nouă de talanți și șapte sute treizeci de șecheli, după șechelul sanctuarului.", "Argintul celor numărați din comunitate a fost de o sută de talanți și o mie șapte sute șaptezeci și cinci de șecheli, după șechelul sanctuarului:", "câte o becă de persoană, adică o jumătate de șechel după șechelul sanctuarului, pentru fiecare dintre cei numărați de la vârsta de douăzeci de ani în sus, în total șase sute trei mii cinci sute cincizeci de bărbați.", "Cei o sută de talanți de argint au fost folosiți pentru turnarea soclurilor sanctuarului și a soclurilor perdelei: o sută de socluri din o sută de talanți, câte un talant pentru fiecare soclu.", "Din cei o mie șapte sute șaptezeci și cinci de șecheli a făcut cârligele stâlpilor, le-a acoperit capitelurile și le-a făcut legăturile.", "Bronzul contribuției a fost de șaptezeci de talanți și două mii patru sute de șecheli.", "Cu el a făcut soclurile de la intrarea Cortului Întâlnirii, altarul de bronz, grătarul lui de bronz, toate uneltele altarului,", "soclurile din jurul curții, soclurile de la intrarea curții, toți țărușii Cortului și toți țărușii din jurul curții."],
    39: ["Din fir albastru, purpuriu și stacojiu au făcut veșmintele lucrate pentru slujirea în Locul Sfânt și au făcut veșmintele sfinte pentru Aaron, așa cum îi poruncise DOMNUL lui Moise.", "Au făcut efodul din aur, fir albastru, purpuriu și stacojiu și din in fin răsucit.", "Au bătut aurul în foi subțiri și l-au tăiat în fire, ca să-l lucreze împreună cu firul albastru, purpuriu și stacojiu și cu inul fin, prin lucrare artistică.", "I-au făcut două bretele unite la cele două capete.", "Brâul țesut al efodului era dintr-o singură bucată cu el și lucrat la fel, din aur, fir albastru, purpuriu și stacojiu și din in fin răsucit, așa cum îi poruncise DOMNUL lui Moise.", "Au prelucrat pietrele de onix, le-au montat în monturi de aur și au gravat pe ele, asemenea gravurii unui sigiliu, numele fiilor lui Israel.", "Le-au pus pe bretelele efodului, ca pietre de aducere-aminte pentru fiii lui Israel, așa cum îi poruncise DOMNUL lui Moise.", "Au făcut pieptarul prin lucrare artistică, la fel ca efodul, din aur, fir albastru, purpuriu și stacojiu și din in fin răsucit.", "Era pătrat și îndoit în două, lung de o palmă și lat de o palmă.", "Au montat în el patru rânduri de pietre. În primul rând: un rubin, un topaz și un smarald;", "în al doilea rând: un turcoaz, un safir și un diamant;", "în al treilea rând: un opal, un agat și un ametist;", "iar în al patrulea rând: un crisolit, un onix și un jasp. Pietrele erau fixate în monturi de aur.", "Pietrele erau douăsprezece, după numele fiilor lui Israel, câte una pentru fiecare nume. Fiecare era gravată asemenea unui sigiliu, cu numele uneia dintre cele douăsprezece seminții.", "Au făcut pentru pieptar lănțișoare din aur curat, ca niște șnururi împletite.", "Au făcut două monturi de aur și două verigi de aur și au pus cele două verigi la cele două capete ale pieptarului.", "Au introdus cele două lănțișoare împletite din aur în cele două verigi de la capetele pieptarului.", "Celelalte două capete ale lănțișoarelor le-au prins de cele două monturi și le-au fixat pe bretelele efodului, în partea din față.", "Au făcut două verigi de aur și le-au pus la celelalte două capete ale pieptarului, pe marginea lui dinspre partea interioară a efodului.", "Au mai făcut două verigi de aur și le-au pus pe cele două bretele ale efodului, în partea de jos și din față, aproape de locul unde se unesc, deasupra brâului țesut al efodului.", "Au legat pieptarul prin verigile lui de verigile efodului cu un șnur albastru, ca să rămână deasupra brâului țesut al efodului și să nu se desprindă de efod, așa cum îi poruncise DOMNUL lui Moise.", "Au făcut mantia efodului, țesută în întregime din fir albastru.", "Deschizătura pentru cap era în mijlocul ei, asemenea deschizăturii unei platoșe, cu o margine țesută în jur, ca să nu se rupă.", "Pe tivul mantiei au făcut rodii din fir albastru, purpuriu și stacojiu și din in răsucit.", "Au făcut clopoței din aur curat și au pus clopoțeii între rodii, de jur împrejurul tivului mantiei:", "un clopoțel și o rodie, un clopoțel și o rodie, de jur împrejurul tivului mantiei pentru slujire, așa cum îi poruncise DOMNUL lui Moise.", "Au făcut tunicile din in fin țesut pentru Aaron și pentru fiii lui,", "turbanul din in fin, bonetele din in fin, pantalonii din in fin răsucit,", "și brâul din in fin răsucit și din fir albastru, purpuriu și stacojiu, lucrat prin broderie, așa cum îi poruncise DOMNUL lui Moise.", "Au făcut plăcuța coroanei sfinte din aur curat și au gravat pe ea, asemenea gravurii unui sigiliu: „SFÂNT PENTRU DOMNUL”.", "Au prins de ea un șnur albastru pentru a o fixa sus, pe turban, așa cum îi poruncise DOMNUL lui Moise.", "Astfel a fost terminată întreaga lucrare a Cortului Întâlnirii. Fiii lui Israel au făcut totul după cum îi poruncise DOMNUL lui Moise; așa au făcut.", "Au adus Cortul la Moise: cortul cu toate obiectele lui, copcile, scândurile, drugii, stâlpii și soclurile,", "învelișul din piei de berbec vopsite în roșu, învelișul din piei fine și perdeaua despărțitoare,", "chivotul Mărturiei cu drugii lui și capacul ispășirii,", "masa cu toate obiectele ei și pâinea Prezenței,", "sfeșnicul curat cu candelele lui așezate în ordine, toate obiectele lui și uleiul pentru lumină,", "altarul de aur, untdelemnul ungerii, tămâia parfumată și paravanul de la intrarea cortului,", "altarul de bronz cu grătarul lui de bronz, drugii și toate uneltele lui, ligheanul și suportul lui,", "pânzele curții, stâlpii, soclurile, paravanul de la intrarea curții, funiile și țărușii ei și toate uneltele pentru slujirea Cortului Întâlnirii,", "veșmintele lucrate pentru slujirea în Locul Sfânt, veșmintele sfinte ale preotului Aaron și veșmintele fiilor lui pentru slujirea preoțească.", "Fiii lui Israel au făcut întreaga lucrare după tot ce îi poruncise DOMNUL lui Moise.", "Moise a cercetat întreaga lucrare și iată că o făcuseră așa cum poruncise DOMNUL. O făcuseră întocmai, iar Moise i-a binecuvântat."],
    40: ["DOMNUL i-a vorbit lui Moise și i-a spus:", "„În prima zi a primei luni să ridici Cortul Întâlnirii.", "Să pui în el chivotul Mărturiei și să ascunzi chivotul în spatele perdelei.", "Să aduci masa și să așezi în ordine lucrurile de pe ea. Să aduci sfeșnicul și să-i aprinzi candelele.", "Să așezi altarul de aur pentru tămâie înaintea chivotului Mărturiei și să pui paravanul la intrarea Cortului.", "Să așezi altarul arderii-de-tot înaintea intrării Cortului Întâlnirii.", "Să așezi ligheanul între Cortul Întâlnirii și altar și să pui apă în el.", "Să ridici curtea de jur împrejur și să atârni paravanul de la intrarea curții.", "Să iei untdelemnul ungerii și să ungi Cortul și tot ce este în el; să-l sfințești împreună cu toate obiectele lui, iar el va fi sfânt.", "Să ungi altarul arderii-de-tot și toate uneltele lui; să sfințești altarul, iar altarul va fi preasfânt.", "Să ungi ligheanul și suportul lui și să-l sfințești.", "Să-i aduci pe Aaron și pe fiii lui la intrarea Cortului Întâlnirii și să-i speli cu apă.", "Să-l îmbraci pe Aaron cu veșmintele sfinte, să-l ungi și să-l sfințești ca să-Mi slujească în preoție.", "Să-i aduci pe fiii lui și să-i îmbraci cu tunicile.", "Să-i ungi așa cum l-ai uns pe tatăl lor, ca să-Mi slujească în preoție. Ungerea lor le va conferi o preoție veșnică din generație în generație.”", "Moise a făcut întocmai; a făcut totul după cum îi poruncise DOMNUL.", "În prima lună a anului al doilea, în prima zi a lunii, Cortul a fost ridicat.", "Moise a ridicat Cortul, i-a așezat soclurile, i-a ridicat scândurile, i-a introdus drugii și i-a ridicat stâlpii.", "A întins acoperământul peste cort și a pus deasupra învelișul Cortului, așa cum îi poruncise DOMNUL lui Moise.", "A luat Mărturia și a pus-o în chivot, a așezat drugii la chivot și a pus capacul ispășirii deasupra chivotului.", "A adus chivotul în Cort, a atârnat perdeaua despărțitoare și a ascuns chivotul Mărturiei, așa cum îi poruncise DOMNUL lui Moise.", "A pus masa în Cortul Întâlnirii, pe latura de nord a Cortului, dincoace de perdea.", "A așezat pe ea pâinea în ordine înaintea DOMNULUI, așa cum îi poruncise DOMNUL lui Moise.", "A pus sfeșnicul în Cortul Întâlnirii, în fața mesei, pe latura de sud a Cortului.", "A aprins candelele înaintea DOMNULUI, așa cum îi poruncise DOMNUL lui Moise.", "A pus altarul de aur în Cortul Întâlnirii, înaintea perdelei,", "și a ars pe el tămâie parfumată, așa cum îi poruncise DOMNUL lui Moise.", "A pus paravanul la intrarea Cortului.", "A așezat altarul arderii-de-tot la intrarea Cortului Întâlnirii și a adus pe el arderea-de-tot și darul de mâncare, așa cum îi poruncise DOMNUL lui Moise.", "A așezat ligheanul între Cortul Întâlnirii și altar și a pus în el apă pentru spălare.", "Moise, Aaron și fiii lui își spălau în el mâinile și picioarele.", "Când intrau în Cortul Întâlnirii și când se apropiau de altar, se spălau, așa cum îi poruncise DOMNUL lui Moise.", "A ridicat curtea de jur împrejurul Cortului și altarului și a pus paravanul de la intrarea curții. Astfel, Moise a terminat lucrarea.", "Atunci norul a acoperit Cortul Întâlnirii, iar gloria DOMNULUI a umplut Cortul.", "Moise nu a putut să intre în Cortul Întâlnirii, fiindcă norul rămânea deasupra lui, iar gloria DOMNULUI umplea Cortul.", "Ori de câte ori norul se ridica de deasupra Cortului, fiii lui Israel porneau mai departe în toate călătoriile lor.", "Dar dacă norul nu se ridica, ei nu porneau până în ziua în care se ridica.", "Norul DOMNULUI era deasupra Cortului ziua, iar noaptea era foc în el, înaintea ochilor întregii case a lui Israel, în toate călătoriile lor."],
  },
}
